function deepClone(obj) { return JSON.parse(JSON.stringify(obj)); }
function darkenHex(hex, amount) {
  const m = /^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(hex || "");
  if (!m) return hex;
  const scale = (h) => Math.max(0, Math.min(255, Math.round(parseInt(h, 16) * (1 - amount))));
  const toHex = (n) => n.toString(16).padStart(2, "0");
  return `#${toHex(scale(m[1]))}${toHex(scale(m[2]))}${toHex(scale(m[3]))}`;
}
function lightenHex(hex, amount) {
  const m = /^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(hex || "");
  if (!m) return hex;
  const scale = (h) => { const c = parseInt(h, 16); return Math.max(0, Math.min(255, Math.round(c + (255 - c) * amount))); };
  const toHex = (n) => n.toString(16).padStart(2, "0");
  return `#${toHex(scale(m[1]))}${toHex(scale(m[2]))}${toHex(scale(m[3]))}`;
}
function relLuminance(hex) {
  const m = /^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(hex || "");
  if (!m) return 1;
  const chan = (h) => {
    const c = parseInt(h, 16) / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  };
  const [r, g, b] = [chan(m[1]), chan(m[2]), chan(m[3])];
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrastRatio(hexA, hexB) {
  const l1 = relLuminance(hexA), l2 = relLuminance(hexB);
  const [lighter, darker] = l1 >= l2 ? [l1, l2] : [l2, l1];
  return (lighter + 0.05) / (darker + 0.05);
}
function applyThemeVars(theme, branding) {
  const root = document.documentElement.style;
  root.setProperty("--primary", theme.primary);
  // --primary-deep/--primary-soft aren't admin-exposed controls, but many
  // elements (hover states, wallet hero, login panel, admin sidebar
  // gradient) derive from them — auto-shade so they stay coherent with
  // whatever Primary is set to, instead of drifting from a stale hardcoded value.
  root.setProperty("--primary-deep", darkenHex(theme.primary, 0.22));
  root.setProperty("--primary-soft", lightenHex(theme.primary, 0.18));
  root.setProperty("--accent", theme.accent);
  root.setProperty("--bg", theme.background);
  root.setProperty("--card", theme.surface);
  root.setProperty("--ink", theme.text);
  root.setProperty("--muted", theme.textMuted);
  root.setProperty("--line", theme.border);
  root.setProperty("--success", theme.success);
  root.setProperty("--danger", theme.danger);
  root.setProperty("--header-bg-start", theme.headerBg);
  root.setProperty("--header-bg-end", darkenHex(theme.headerBg, 0.22));
  root.setProperty("--footer-bg", theme.footerBg);
  root.setProperty("--logo-size", { small: "36px", medium: "44px", large: "56px" }[branding.logoSize] || "44px");
}

