// ---------- Combo & BOGO promotions ----------
// Combo bundles live on the "deals" home section (State.homeSections,
// admin-editable via the Deals & Combos tile-list editor); BOGO is a flag on
// the product itself (Catalog). SEED_COMBOS (see SEED_HOME_SECTIONS, below)
// is what these seed from and what the one-time backfill falls back to.
function allCombos() {
  const s = State.homeSections.find((x) => x.type === "deals");
  return (s && s.combos) || [];
}
function isBogo(id) { const it = findItem(id); return !!(it && it.bogo); }
function comboEligible(combo) { return combo.itemIds.every((id) => (State.cart[id] || 0) >= 1); }
function comboIndividualTotal(combo) {
  return combo.itemIds.reduce((s, id) => { const it = findItem(id); return s + (it ? it.price : 0); }, 0);
}
// A combo's limit (type + quantity) as the form sent it. Round 13 supplies it; nothing before it had one.
function comboCapFields(fd) { return {}; }
function comboSavings(combo) { return Math.max(comboIndividualTotal(combo) - combo.bundlePrice, 0); }
function activeCombos() { return allCombos().filter(comboEligible); }
function activeComboSavings() { return activeCombos().reduce((s, c) => s + comboSavings(c), 0); }

// ---------- Coupons ----------
function findCouponByCode(code) {
  const norm = String(code || "").trim().toUpperCase();
  if (!norm) return null;
  return State.coupons.find((c) => c.code.toUpperCase() === norm) || null;
}
function couponEligibility(coupon, subtotal) {
  if (!coupon) return { ok: false, reason: "Invalid coupon code" };
  if (!coupon.enabled) return { ok: false, reason: "This coupon is no longer active" };
  if (coupon.expiresAt && Date.now() > coupon.expiresAt) return { ok: false, reason: "This coupon has expired" };
  if (subtotal < (coupon.minOrder || 0)) return { ok: false, reason: `Add ${money(coupon.minOrder - subtotal)} more to use ${coupon.code}` };
  return { ok: true };
}
function couponDiscountAmount(coupon, subtotal) {
  if (!coupon) return 0;
  if (coupon.type === "percent") {
    const raw = subtotal * (coupon.value / 100);
    return coupon.maxDiscount ? Math.min(raw, coupon.maxDiscount) : raw;
  }
  if (coupon.type === "flat") return Math.min(coupon.value, subtotal);
  return 0;
}

// Store-fulfilment order lifecycle. New/Confirmed/Preparing are the store's
// own prep stages (D108: picking and packing are one step) (Store Manager-driven); Ready for Rider is when the branch's
// round-robin queue takes over; Picked Up/Delivered are rider-driven.
const STATUS_META = {
  new: { label: "New", tone: "yellow" },
  confirmed: { label: "Confirmed", tone: "yellow" },
  picking: { label: "Preparing", tone: "yellow" },
  ready_for_rider: { label: "Ready for Rider", tone: "blue" },
  picked_up: { label: "Picked Up", tone: "blue" },
  delivered: { label: "Delivered", tone: "green" },
  cancelled: { label: "Cancelled", tone: "red" },
  returned: { label: "Returned", tone: "red" },
};
const TIMELINE_STEPS = ["new", "confirmed", "picking", "ready_for_rider", "picked_up", "delivered"];
// Store-side prep — no rider involved yet, managed by Store Manager/Admin.
const PREP_STATUSES = ["new", "confirmed", "picking"];
// Rider-facing lifecycle — order has (or is waiting for) a rider.
const DISPATCH_STATUSES = ["ready_for_rider", "picked_up"];
// End states — nothing left to advance.
const TERMINAL_STATUSES = ["delivered", "cancelled", "returned"];
// Advance-to-next-stage button label per store-prep status, keyed by the
// CURRENT status (the button moves it to the next TIMELINE_STEPS entry).
const ADVANCE_LABEL = {
  new: "Confirm order",
  confirmed: "Start preparing",
  picking: "Mark ready for rider",
};
// Earlier prototype versions used a 4-stage status set (placed/assigned/
// out_for_delivery/...) before it became the 7-stage store-fulfilment flow.
// Anyone with orders already saved in their browser's localStorage from that
// version would otherwise hit `STATUS_META[order.status]` being undefined and
// crash the whole render (a blank page) — this maps old values onto their
// closest new equivalent so existing local data self-heals instead.
const LEGACY_STATUS_MAP = { placed: "new", assigned: "ready_for_rider", out_for_delivery: "picked_up" };
function normaliseOrderStatus(status) {
  if (STATUS_META[status]) return status;
  return LEGACY_STATUS_MAP[status] || "new";
}

