const DEFAULT_COORDS = [1.3521, 103.8198]; // central Singapore fallback for sectors not in the table above

function estimateCoordsFromPostal(postal) {
  const sector = String(postal || "").trim().slice(0, 2);
  return POSTAL_SECTOR_COORDS[sector] || DEFAULT_COORDS;
}

function haversineKm(lat1, lng1, lat2, lng2) {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLng = ((lng2 - lng1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// Nearest active branch that can actually reach this postal code (distance <= its
// service radius). Returns null when no branch is in range — a real "not
// deliverable to your area yet" case, not a bug.
function findServiceableBranch(postal, branches) {
  const [lat, lng] = estimateCoordsFromPostal(postal);
  let best = null, bestDist = Infinity;
  for (const b of branches || []) {
    if (!b.active) continue;
    const d = haversineKm(lat, lng, b.lat, b.lng);
    if (d <= b.radiusKm && d < bestDist) { best = b; bestDist = d; }
  }
  return best ? { branch: best, distanceKm: bestDist } : null;
}

