// Demo history so Admin/Rider dashboards aren't empty on first load.
function seedOrders() {
  const names = ["Aarav Mehta", "Siti Nurhaliza", "Wei Jie", "Priya Nair", "Marcus Lim", "Farah Yusof", "Karthik Raj", "Hui Ling"];
  const addrs = [
    "12 Tampines St 41, #05-123, Singapore 521012",
    "88 Bedok North Rd, #10-08, Singapore 460088",
    "5 Jurong West Ave 1, #02-14, Singapore 640005",
    "230 Ang Mo Kio Ave 3, #12-345, Singapore 560230",
  ];
  const mobiles = ["91234501", "82345602", "93456703", "84567804", "95678905", "86789006", "97890107", "88901208"];
  const now = Date.now();
  const orders = [];
  // 2026-09: more orders, clustered around lunch and the evening rush, so the
  // dashboard's Peak hours chart has a realistic shape.
  const hourWeights = [0, 0, 0, 0, 0, 0, 1, 2, 3, 4, 5, 6, 8, 7, 4, 3, 4, 6, 9, 10, 8, 5, 3, 1];
  const pickHour = () => { let r = Math.random() * hourWeights.reduce((a, b) => a + b, 0); for (let h = 0; h < 24; h++) { r -= hourWeights[h]; if (r < 0) return h; } return 19; };
  for (let i = 0; i < 60; i++) {
    const daysAgo = Math.floor(Math.random() * 30);
    const day = new Date(now - daysAgo * 86400000);
    day.setHours(pickHour(), Math.floor(Math.random() * 60), 0, 0);
    let createdAt = day.getTime();
    if (createdAt > now) createdAt -= 86400000;
    const pickCount = 1 + Math.floor(Math.random() * 4);
    const picked = [...SEED_ITEMS].sort(() => 0.5 - Math.random()).slice(0, pickCount)
      .map((it) => ({ id: it.id, name: it.name, unit: it.unit, price: it.price, eta: it.eta, qty: 1 + Math.floor(Math.random() * 3), delivered: null }));
    const total = picked.reduce((s, i) => s + i.price * i.qty, 0);
    const deliveryFee = total < DEFAULT_DELIVERY_SETTINGS.freeDeliveryThreshold ? DEFAULT_DELIVERY_SETTINGS.deliveryFee : 0;
    const r = Math.random();
    let status;
    if (daysAgo === 0 && r < 0.5) {
      const inProgress = ["new", "confirmed", "picking", "ready_for_rider", "picked_up"];
      status = inProgress[Math.floor(Math.random() * inProgress.length)];
    } else status = r < 0.08 ? "cancelled" : r < 0.14 ? "returned" : "delivered";
    const address = addrs[i % addrs.length];
    const postalMatch = address.match(/\d{6}/);
    const served = findServiceableBranch(postalMatch ? postalMatch[0] : "", SEED_BRANCHES);
    const branchId = served ? served.branch.id : null;
    const branchPartners = SEED_PARTNERS.filter((p) => p.branchId === branchId);
    const hasRider = ["ready_for_rider", "picked_up", "delivered"].includes(status);
    const partner = hasRider && branchPartners.length ? branchPartners[Math.floor(Math.random() * branchPartners.length)] : null;
    orders.push({
      id: genId("QK"),
      invoiceNo: genId("INV-"),
      customerName: names[i % names.length],
      contactName: names[i % names.length],
      contactMobile: mobiles[i % mobiles.length],
      address,
      branchId,
      items: picked,
      total: total + deliveryFee,
      deliveryFee,
      walletApplied: 0,
      discount: 0,
      paymentMethod: DEFAULT_DELIVERY_SETTINGS.paymentMethods[i % DEFAULT_DELIVERY_SETTINGS.paymentMethods.length].name,
      status,
      deliveryPartnerId: partner ? partner.id : null,
      rating: status === "delivered" && Math.random() < 0.7 ? 3 + Math.floor(Math.random() * 3) : null,
      riderEarning: status === "delivered" ? RIDER_FLAT_FEE : 0,
      createdAt,
      statusHistory: [{ status: "new", at: createdAt }],
    });
  }
  return orders.sort((a, b) => b.createdAt - a.createdAt);
}


// ====================================================================
// MyShopza Web — desktop storefront. Plain JS, no framework.
// Ported business logic from quickkart-prototype.html; UI rebuilt for
// desktop per the redesign brief (see plan). Renders by rebuilding
// innerHTML of #app from state; event handling is delegated so we
// never need to re-bind listeners after a render.
// ====================================================================

/* ---------------- Utilities ---------------- */
function money(n) { return `S$${(n || 0).toFixed(2)}`; }
// Inclusive: `price` already contains the tax — this backs the tax portion
// out of it for display (doesn't change any total). Exclusive: `price` is
// pre-tax — this is the amount to add on top to reach what's actually charged.
function gstAmount(price, tax) {
  if (!tax) return 0;
  return tax.inclusive === false ? price * (tax.rate / 100) : price * (tax.rate / (100 + tax.rate));
}
function discountPct(i) { return i.mrp > i.price ? Math.round(((i.mrp - i.price) / i.mrp) * 100) : 0; }
function fmtDate(ts) { return new Date(ts).toLocaleDateString("en-SG", { day: "2-digit", month: "short", year: "numeric" }); }
function fmtDateTime(ts) { return new Date(ts).toLocaleString("en-SG", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }); }
function fmtTime(ts) { return new Date(ts).toLocaleTimeString("en-SG", { hour: "2-digit", minute: "2-digit" }); }
// Shift-length readout for the rider's end-of-shift summary — "2h 05m", or
// just "8m" once a shift runs under an hour.
function fmtDuration(ms) {
  const mins = Math.max(0, Math.round(ms / 60000));
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return h > 0 ? `${h}h ${String(m).padStart(2, "0")}m` : `${m}m`;
}
function genId(prefix) { return `${prefix}${Math.floor(10000 + Math.random() * 89999)}`; }
function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function normaliseSgMobile(raw) {
  const digits = String(raw || "").replace(/[^\d]/g, "").replace(/^65(?=\d{8}$)/, "");
  return /^[3689]\d{7}$/.test(digits) ? digits : null;
}
function fmtMobile(m) {
  const d = String(m || "").replace(/[^\d]/g, "");
  return d.length === 8 ? `+65 ${d.slice(0, 4)} ${d.slice(4)}` : (m || "—");
}
function telHref(phone) { return `tel:${String(phone || "").replace(/[^\d+]/g, "")}`; }

