// One-time backfill for a home section saved before its content type (tiles
// or combos) became admin-editable. `=== undefined` is deliberate, not a
// falsy check — an empty array is a legitimate "admin deleted everything"
// state and must never be silently re-seeded back on a later reload.
function backfillSectionContent(s) {
  const seed = SEED_HOME_SECTIONS.find((x) => x.type === s.type);
  if (TILE_TYPE_CONFIG[s.type] && s.tiles === undefined) return { ...s, tiles: (seed && seed.tiles) || [] };
  if (s.type === "deals" && s.combos === undefined) return { ...s, combos: (seed && seed.combos) || [] };
  return s;
}

