/* ---------------- Derived business logic (ported from CustomerApp) ---------------- */
function getSelectedAddress() {
  const addrs = State.profile.addresses;
  return addrs.find((a) => a.id === UI.selectedAddressId) || addrs.find((a) => a.isDefault) || addrs[0] || null;
}
function cartLineName(item) {
  // Many product names end with their own pack size (e.g. "Bananas (6pc)",
  // "Alphonso Mangoes 1kg") which the cart already shows on its own line via
  // `unit` — strip that trailing duplicate so it's not shown twice.
  const escaped = item.unit.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s*");
  const trailingUnit = new RegExp("\\s*\\(?\\s*" + escaped + "\\s*\\)?\\s*$", "i");
  const stripped = item.name.replace(trailingUnit, "").trim();
  return stripped || item.name;
}
function cartLines() {
  return State.items.filter((i) => State.cart[i.id] > 0).map((i) => ({ ...i, qty: State.cart[i.id] }));
}
function cartTotals() {
  const cartItems = cartLines();
  const totalMrp = cartItems.reduce((s, i) => s + i.mrp * i.qty, 0);
  const grossPrice = cartItems.reduce((s, i) => s + i.price * i.qty, 0);
  const savings = totalMrp - grossPrice;
  const bogoSavings = cartItems.reduce((s, i) => s + (isBogo(i.id) ? i.price * Math.floor(i.qty / 2) : 0), 0);
  const comboDiscount = activeComboSavings();
  const totalPrice = Math.max(grossPrice - bogoSavings - comboDiscount, 0);
  const appliedCoupon = UI.appliedCoupon ? findCouponByCode(UI.appliedCoupon) : null;
  const couponCheck = appliedCoupon ? couponEligibility(appliedCoupon, totalPrice) : null;
  const couponValid = !!(couponCheck && couponCheck.ok);
  const couponFreeShip = couponValid && appliedCoupon.type === "freeship";
  const couponDiscount = couponValid && !couponFreeShip ? couponDiscountAmount(appliedCoupon, totalPrice) : 0;
  const priceAfterCoupon = Math.max(totalPrice - couponDiscount, 0);
  const deliveryFee = UI.fulfillment === "pickup" || couponFreeShip ? 0 : (priceAfterCoupon > 0 && priceAfterCoupon < State.deliverySettings.freeDeliveryThreshold ? State.deliverySettings.deliveryFee : 0);
  const gst = gstAmount(priceAfterCoupon, State.tax);
  // Inclusive: gst is just the already-included portion, so it never touches
  // the total. Exclusive: it's added on top of the discounted subtotal here,
  // before delivery fee/wallet — the one place tax actually changes a total.
  const taxInclusive = !State.tax || State.tax.inclusive !== false;
  // 2026-09: Express charge — on top of the delivery fee; free delivery / a
  // free-delivery coupon doesn't waive it.
  const expressCharge = UI.fulfillment !== "pickup" && expressEnabled() && UI.deliverySpeed === "express" && priceAfterCoupon > 0 ? expressChargeAmount() : 0;
  const payableBeforeWallet = priceAfterCoupon + (taxInclusive ? 0 : gst) + deliveryFee + expressCharge;
  const walletUsable = State.wallet > 0;
  const walletApplied = UI.useWallet && walletUsable ? Math.min(State.wallet, payableBeforeWallet) : 0;
  const grandTotal = Math.max(payableBeforeWallet - walletApplied, 0);
  const cartCount = Object.values(State.cart).reduce((a, b) => a + b, 0);
  return { cartItems, totalMrp, grossPrice, totalPrice, savings, bogoSavings, comboDiscount, appliedCoupon, couponCheck, couponValid, couponFreeShip, couponDiscount, priceAfterCoupon, deliveryFee, expressCharge, gst, taxInclusive, payableBeforeWallet, walletUsable, walletApplied, grandTotal, cartCount };
}
