/* ---------------- Home screen section registry ---------------- */
function sortedHomeSections() {
  return State.homeSections.slice().sort((a, b) => a.order - b.order);
}
// Moves `draggedId` to sit where `targetId` currently is, then renumbers
// every section's `order` sequentially so ties can never reappear.
function reorderHomeSection(draggedId, targetId) {
  const list = sortedHomeSections();
  const fromIdx = list.findIndex((s) => s.id === draggedId);
  const toIdx = list.findIndex((s) => s.id === targetId);
  if (fromIdx === -1 || toIdx === -1 || fromIdx === toIdx) return;
  const [moved] = list.splice(fromIdx, 1);
  list.splice(toIdx, 0, moved);
  // Rebuild fresh objects rather than mutating s.order in place — the seed
  // array's objects aren't deep-cloned by loadLS's fallback, so mutating
  // them here would corrupt SEED_HOME_SECTIONS itself for the rest of the
  // page's lifetime.
  State.homeSections = list.map((s, i) => ({ ...s, order: i + 1 }));
  persist("homeSections");
  render();
}
// Same generic ordering helpers, one level down — for the tiles/combos that
// live *on* a single section (see TILE_TYPE_CONFIG), not the sections list.
function sortedTiles(section) {
  return (section.tiles || []).slice().sort((a, b) => a.order - b.order);
}
function sortedCombos(section) {
  return (section.combos || []).slice().sort((a, b) => a.order - b.order);
}
function reorderSectionTiles(sectionId, draggedId, targetId) {
  const section = State.homeSections.find((s) => s.id === sectionId);
  if (!section) return;
  const list = sortedTiles(section);
  const fromIdx = list.findIndex((t) => t.id === draggedId);
  const toIdx = list.findIndex((t) => t.id === targetId);
  if (fromIdx === -1 || toIdx === -1 || fromIdx === toIdx) return;
  const [moved] = list.splice(fromIdx, 1);
  list.splice(toIdx, 0, moved);
  const tiles = list.map((t, i) => ({ ...t, order: i + 1 }));
  State.homeSections = State.homeSections.map((s) => s.id === sectionId ? { ...s, tiles } : s);
  persist("homeSections");
  render();
}
function reorderCombos(sectionId, draggedId, targetId) {
  const section = State.homeSections.find((s) => s.id === sectionId);
  if (!section) return;
  const list = sortedCombos(section);
  const fromIdx = list.findIndex((c) => c.id === draggedId);
  const toIdx = list.findIndex((c) => c.id === targetId);
  if (fromIdx === -1 || toIdx === -1 || fromIdx === toIdx) return;
  const [moved] = list.splice(fromIdx, 1);
  list.splice(toIdx, 0, moved);
  const combos = list.map((c, i) => ({ ...c, order: i + 1 }));
  State.homeSections = State.homeSections.map((s) => s.id === sectionId ? { ...s, combos } : s);
  persist("homeSections");
  render();
}
function renderHomeSection(s, pools) {
  switch (s.type) {
    case "hero": return heroBanner();
    case "verticalTiles": return verticalTilesHTML(s);
    case "deals": return dealsSectionHTML(s);
    case "offerTiles": return offerTilesHTML(s);
    case "freshSpotlight": return freshSpotlightHTML(pools.fresh, s);
    case "secondaryBanner": return secondaryBannerHTML(s);
    case "trustStrip": return trustStripHTML(s);
    case "recentlyViewed": return pools.recent.length ? productRail("Recently Viewed", pools.recent) : "";
    case "rail": return productRail(s.title, pools[s.poolKey] || [], { seeAllTag: s.seeAllTag });
    case "promo": return customPromoSectionHTML(s);
    default: return "";
  }
}
// Admin-created sections: a banner (title/subtitle/image) plus an optional
// rail of hand-picked products — same visual language as the built-in
// secondaryBannerHTML band, so it doesn't look bolted on.
function customPromoSectionHTML(s) {
  const items = (s.itemIds || []).map((id) => findItem(id)).filter((i) => i && i.stock);
  return `
  <section class="container section">
    <div class="promo-banner" style="background-image:linear-gradient(100deg, rgba(0,61,114,.9), rgba(0,61,114,.35) 68%), url('${s.image || img("photo-1604118464816-5e2bd7b863c2", 1400)}')">
      <div class="promo-banner-copy">
        <h2>${esc(s.title)}</h2>
        ${s.subtitle ? `<p>${esc(s.subtitle)}</p>` : ""}
      </div>
    </div>
    ${items.length ? `<div class="rail" style="margin-top:16px">${items.map((item) => productCardHTML(item)).join("")}</div>` : ""}
  </section>`;
}
function viewHome() {
  // Each product appears in at most one curated rail — a shared `used` set
  // walks the rails in order so a bestseller-and-offer item (e.g. Bananas)
  // doesn't show up again in every later section.
  const used = new Set();
  const take = (pool, limit) => {
    const out = [];
    for (const item of pool) {
      if (used.has(item.id)) continue;
      out.push(item);
      used.add(item.id);
      if (out.length >= limit) break;
    }
    return out;
  };
  // Fresh is taken first so the home page's Fresh Picks spotlight — the most
  // visually prominent rail after Popular Near You — reliably gets stock;
  // otherwise its (small) tag pool gets fully absorbed by trending/bestseller/
  // offer picks before its turn and the spotlight renders empty.
  const catalog = State.items.map(withBranchStock);
  const fresh = take(catalog.filter((i) => i.stock && (i.tags || []).includes("fresh")), 10);
  const trending = take(trendingItems(30), 10);
  const bestSellers = take(catalog.filter((i) => i.stock && (i.tags || []).includes("bestseller")), 10);
  const offers = take(catalog.filter((i) => i.stock && i.mrp > i.price), 10);
  const indian = take(catalog.filter((i) => i.stock && (i.tags || []).includes("indian")), 10);
  const sg = take(catalog.filter((i) => i.stock && (i.tags || []).includes("sg")), 10);
  const recent = State.recentlyViewed.map((id) => findItem(id)).filter(Boolean).slice(0, 8);
  const pools = { trending, bestSellers, fresh, offers, indian, sg, recent };
  return sortedHomeSections().filter((s) => s.enabled).map((s) => renderHomeSection(s, pools)).join("");
}

/* ---------------- Product card ---------------- */
function productCardHTML(item) {
  const qty = State.cart[item.id] || 0;
  const pct = discountPct(item);
  const lowStock = item.stock && item.stockCount != null && item.stockCount <= 5;
  const saved = isWishlisted(item.id);
  return `
  <div class="p-card ${!item.stock ? "p-card-oos" : ""}">
    ${!item.stock ? `
      <div class="p-card-oos-overlay">
        <span class="p-card-oos-label">Out of stock</span>
        <button class="btn btn-primary btn-sm" data-action="notify-me" data-id="${item.id}">Notify when back</button>
        <button class="link-btn" data-action="open-product" data-id="${item.id}">View options →</button>
      </div>` : ""}
    <div class="p-card-badges">
      ${item.stock && isBogo(item.id) ? `<span class="badge badge-green">Buy 1 Get 1</span>` : pct > 0 && item.stock ? `<span class="badge badge-red">${pct}% off</span>` : "<span></span>"}
    </div>
    <button class="p-card-wish ${saved ? "active" : ""}" data-action="toggle-wishlist" data-id="${item.id}" aria-label="${saved ? "Remove from wishlist" : "Save to wishlist"}" aria-pressed="${saved}">${ic("heart")}</button>
    <button class="p-card-media" data-action="open-product" data-id="${item.id}" aria-label="View ${esc(item.name)}">
      <img src="${item.image}" alt="${esc(item.name)}" loading="lazy" />
    </button>
    <button class="p-card-body" data-action="open-product" data-id="${item.id}">
      <div class="p-card-eta">${ic("truck")}Delivery</div>
      ${item.brand ? `<div class="p-card-brand">${esc(item.brand)}</div>` : ""}
      <div class="p-card-name">${esc(item.name)}</div>
      <div class="p-card-unit">${esc(item.unit)}</div>
      ${lowStock ? `<div class="p-card-lowstock">Only ${item.stockCount} left</div>` : ""}
    </button>
    <div class="p-card-foot">
      <div class="p-card-price">
        <span class="p-card-price-now">${money(item.price)}</span>
        ${pct > 0 ? `<span class="p-card-price-mrp">${money(item.mrp)}</span>` : ""}
      </div>
      ${item.stock ? (qty > 0 ? `
        <div class="qty-stepper">
          <button data-action="dec-cart" data-id="${item.id}" aria-label="Remove one">${ic("minus")}</button>
          <span>${qty}</span>
          <button data-action="inc-cart" data-id="${item.id}" aria-label="Add one">${ic("plus")}</button>
        </div>` : `
        <button class="btn btn-outline btn-sm" data-action="inc-cart" data-id="${item.id}">ADD</button>`
      ) : ""}
    </div>
  </div>`;
}

/* ---------------- Shop (browse / search results) ---------------- */
/* ---------------- Keyword search ---------------- */
// Real grocery apps match on more than an exact name: brand, category and
// tags all count as "keywords" a shopper might type (e.g. "amul", "chips").
function searchTokens(q) {
  return String(q || "").trim().toLowerCase().split(/\s+/).filter(Boolean);
}
function itemHaystack(i) {
  return [i.name, i.brand, i.cat, i.unit, ...(i.tags || [])].filter(Boolean).join(" ").toLowerCase();
}
function itemMatchesQuery(i, tokens) {
  if (!tokens.length) return true;
  const hay = itemHaystack(i);
  return tokens.every((t) => hay.includes(t));
}
function matchingCategories(q, limit) {
  const s = String(q || "").trim().toLowerCase();
  if (!s) return [];
  return State.categories.filter((c) => c.name.toLowerCase().includes(s)).slice(0, limit || 3);
}

const PRICE_RANGES = {
  "0-5": { label: "Under S$5", test: (p) => p < 5 },
  "5-10": { label: "S$5 – S$10", test: (p) => p >= 5 && p <= 10 },
  "10-20": { label: "S$10 – S$20", test: (p) => p > 10 && p <= 20 },
  "20-plus": { label: "Above S$20", test: (p) => p > 20 },
};
function availableBrands() {
  const searchingAll = UI.cat === ALL_CATEGORIES;
  const pool = searchingAll ? State.items : State.items.filter((i) => i.cat === UI.cat);
  return [...new Set(pool.map((i) => i.brand).filter(Boolean))].sort();
}
function filteredItemsBase() {
  // Everything except brand/price/discount/stock — used to compute filter
  // option counts so the sidebar reflects the current category/search scope.
  const tokens = searchTokens(UI.query);
  const searchingAll = UI.cat === ALL_CATEGORIES;
  return State.items
    .map(withBranchStock)
    .filter((i) => searchingAll || i.cat === UI.cat)
    .filter((i) => !UI.tagFilter || (i.tags || []).includes(UI.tagFilter))
    .filter((i) => itemMatchesQuery(i, tokens));
}
function filteredItems() {
  return filteredItemsBase()
    .filter((i) => !UI.inStockOnly || i.stock)
    .filter((i) => !UI.brandFilter.length || UI.brandFilter.includes(i.brand))
    .filter((i) => !UI.priceRange || PRICE_RANGES[UI.priceRange].test(i.price))
    .filter((i) => !UI.discountFilter || discountPct(i) >= Number(UI.discountFilter))
    .sort((a, b) => {
      if (UI.shopSort === "price-asc") return a.price - b.price;
      if (UI.shopSort === "price-desc") return b.price - a.price;
      if (UI.shopSort === "discount") return discountPct(b) - discountPct(a);
      if (UI.shopSort === "popularity") return Number((b.tags || []).includes("bestseller")) - Number((a.tags || []).includes("bestseller"));
      if (UI.shopSort === "newest") return b.id - a.id;
      return 0;
    });
}

function hasAdvancedFilters() {
  return !!(UI.priceRange || UI.discountFilter || UI.inStockOnly || UI.brandFilter.length);
}
// Badge count for the mobile Filter pill — mirrors hasAdvancedFilters()'s
// checks, one per active filter (brand counted per-brand, not as one).
function advancedFilterCount() {
  return (UI.priceRange ? 1 : 0) + (UI.discountFilter ? 1 : 0) + (UI.inStockOnly ? 1 : 0) + UI.brandFilter.length;
}
function activeFilterChipsHTML() {
  // Browsing a category alone (from the catnav pill) isn't "a filter" from
  // the user's point of view — only show this summary once they've actually
  // picked something from the Filter sheet or a quick-filter tag, matching
  // emptyResultsHTML()'s existing "filtered" definition below.
  if (!hasAdvancedFilters() && !UI.tagFilter) return "";
  const chips = [];
  if (UI.cat !== ALL_CATEGORIES) chips.push({ kind: "cat", label: esc(UI.cat) });
  if (UI.tagFilter) chips.push({ kind: "tag", label: tagLabel(UI.tagFilter) });
  if (UI.priceRange) chips.push({ kind: "price", label: PRICE_RANGES[UI.priceRange].label });
  if (UI.discountFilter) chips.push({ kind: "discount", label: `${UI.discountFilter}% off or more` });
  if (UI.inStockOnly) chips.push({ kind: "stock", label: "In stock only" });
  UI.brandFilter.forEach((b) => chips.push({ kind: "brand", label: esc(b), value: esc(b) }));
  if (!chips.length) return "";
  return `
  <div class="active-filters" id="activeFilters">
    ${chips.map((c) => `<button class="filter-chip" data-action="remove-active-filter" data-kind="${c.kind}" data-value="${c.value || ""}">${c.label}${ic("close")}</button>`).join("")}
    <button class="link-btn" data-action="clear-shop-filters">Clear all</button>
  </div>`;
}
