// Steps now mirror the order's real store-fulfilment status directly (see
// STATUS_META/TIMELINE_STEPS) rather than faking sub-stages from elapsed time —
// New/Confirmed/Picking/Packing are real store-prep stages a Store Manager or
// Admin advances by hand. Pickup orders skip the rider stages entirely.
function orderTimelineSteps(order) {
  const isPickup = order.fulfillment === "pickup";
  const currentIdx = TIMELINE_STEPS.indexOf(order.status);
  const steps = isPickup ? [
    { key: "new", label: "Order Placed" },
    { key: "confirmed", label: "Order Confirmed" },
    { key: "picking", label: "Preparing Your Order" },
    { key: "ready_for_rider", label: "Ready for Pickup" },
    { key: "delivered", label: "Picked Up" },
  ] : [
    { key: "new", label: "Order Placed" },
    { key: "confirmed", label: "Order Confirmed" },
    { key: "picking", label: "Preparing Your Order" },
    { key: "ready_for_rider", label: "Packed — waiting for a rider" },
    { key: "picked_up", label: "Out for Delivery" },
    { key: "delivered", label: "Delivered" },
  ];
  let markedCurrent = false;
  return steps.map((s) => {
    const done = order.status === "delivered" || TIMELINE_STEPS.indexOf(s.key) <= currentIdx;
    if (!done && !markedCurrent) { markedCurrent = true; return { ...s, current: true, done }; }
    return { ...s, current: false, done };
  });
}
function currentStepInfo(order) {
  if (order.status === "cancelled") return { label: "Order Cancelled", desc: "This order was cancelled." };
  if (order.status === "returned") return { label: "Order Returned", desc: "This order was returned." };
  const steps = orderTimelineSteps(order);
  const current = steps.find((s) => s.current) || steps[steps.length - 1];
  const isPickup = order.fulfillment === "pickup";
  const descriptions = {
    new: "We've received your order.",
    confirmed: "Your order has been confirmed by the store.",
    picking: "Your items are being picked and packed.",
    ready_for_rider: isPickup ? "Your order is packed and ready for pickup." : "Your order is packed and waiting for a rider.",
    picked_up: "Your rider is on the way.",
    delivered: isPickup ? "Picked up — enjoy!" : "Delivered — enjoy!",
  };
  return { label: current.label, desc: descriptions[current.key] || "" };
}
function orderStatusBannerHTML(order) {
  const bad = order.status === "cancelled" || order.status === "returned";
  const done = order.status === "delivered";
  const info = currentStepInfo(order);
  const icon = bad ? "alert" : done ? "check" : order.fulfillment === "pickup" ? "store" : "truck";
  return `
  <div class="status-banner ${bad ? "status-banner-bad" : done ? "status-banner-done" : ""}">
    <div class="status-banner-icon">${ic(icon)}</div>
    <div class="status-banner-text">
      <div class="status-banner-label">${esc(info.label)}</div>
      <div class="qk-muted small">${esc(info.desc)}</div>
    </div>
    ${!bad && !done && order.scheduledSlot ? `<div class="status-banner-eta">${esc(order.scheduledSlot)}</div>` : ""}
  </div>`;
}
function timelineStepsHTML(steps) {
  return `
  <div class="timeline">
    ${steps.map((step, idx) => {
      const last = idx === steps.length - 1;
      return `
      <div class="timeline-row">
        <div class="timeline-dotcol">
          <div class="timeline-dot ${step.done ? "done" : ""} ${step.current ? "current" : ""}">${step.done ? ic("check") : ""}</div>
          ${!last ? `<div class="timeline-line ${step.done ? "done" : ""}"></div>` : ""}
        </div>
        <div class="timeline-label ${step.done ? "done" : ""} ${step.current ? "current" : ""}">${esc(step.label)}</div>
      </div>`;
    }).join("")}
  </div>`;
}
function orderTimelineHTML(order) {
  const partner = findPartner(order.deliveryPartnerId);
  const bad = order.status === "cancelled" || order.status === "returned";
  if (bad) return `<span class="badge badge-red">${STATUS_META[order.status].label}</span>`;
  return `${timelineStepsHTML(orderTimelineSteps(order))}${partner ? `<div class="qk-muted small">${ic("truck")} ${esc(partner.name)} is delivering your order</div>` : ""}`;
}

// ---------- Return / replacement request pipeline (simulated auto-progression) ----------
const RETURN_STEPS = [
  { key: "submitted", label: "Request Submitted", minElapsedMin: 0 },
  { key: "under_review", label: "Under Review", minElapsedMin: 1 },
  { key: "approved", label: "Approved", minElapsedMin: 2 },
  { key: "processing", label: "Processing", minElapsedMin: 4 },
  { key: "completed", label: "Completed", minElapsedMin: 6 },
];
function returnRequestCurrentKey(rr) {
  const elapsed = (Date.now() - rr.createdAt) / 60000;
  let current = RETURN_STEPS[0].key;
  RETURN_STEPS.forEach((step) => { if (elapsed >= step.minElapsedMin) current = step.key; });
  return current;
}
function returnRequestSteps(rr) {
  const currentKey = returnRequestCurrentKey(rr);
  const currentIdx = RETURN_STEPS.findIndex((s) => s.key === currentKey);
  const verb = rr.resolution === "replacement" ? "Replacement" : "Refund";
  return RETURN_STEPS.map((step, idx) => ({
    key: step.key,
    label: step.key === "processing" ? `${verb} Processing` : step.key === "completed" ? `${verb} Completed` : step.label,
    done: idx <= currentIdx,
    current: idx === currentIdx,
  }));
}
function returnRequestHTML(order) {
  const rr = order.returnRequest;
  if (!rr) return "";
  return `
  <div class="summary-card">
    <div class="summary-card-title">${rr.resolution === "replacement" ? "Replacement" : "Refund"} status</div>
    <div class="qk-muted small" style="margin-bottom:10px">Reason: ${esc(rr.reason)}</div>
    ${timelineStepsHTML(returnRequestSteps(rr))}
  </div>`;
}
function syncReturnRequest(order) {
  const rr = order.returnRequest;
  if (!rr || rr.finalized) return;
  if (returnRequestCurrentKey(rr) !== "completed") return;
  const idx = State.orders.findIndex((o) => o.id === order.id);
  if (idx === -1) return;
  State.orders[idx] = { ...State.orders[idx], status: "returned", returnRequest: { ...rr, finalized: true } };
  if (rr.resolution === "refund") {
    State.wallet += order.total; persist("wallet");
    pushNotice(`Refund of ${money(order.total)} credited to your wallet for order #${order.id}.`);
  } else {
    pushNotice(`Your replacement for order #${order.id} has been processed and will be delivered separately.`);
  }
  persist("orders");
}

