/* ---------------- Orders & Help ---------------- */
// Only place in this rework where JS reads viewport width directly (D6
// otherwise keeps this a pure CSS-reflow app) — needed because D12's
// scroll-offset requirement can only be honored if JS knows whether
// Orders is currently in stacked list/detail mode (<=1024px, the same
// tier boundary the CSS below uses to toggle .orders-layout) or desktop's
// permanent side-by-side layout, where selecting an order must not move
// window scroll at all (D1: desktop unchanged).
function ordersStacked() { return window.matchMedia("(max-width: 1024px)").matches; }

function viewOrders() {
  myOrders().forEach(syncReturnRequest);
  const orders = myOrders();
  if (!orders.length) {
    return `
    <div class="container section">
      <div class="empty-state empty-wide">
        <div class="empty-title">No orders yet</div>
        <div class="empty-hint">Once you place an order it'll show up here, with tracking and your invoice.</div>
      </div>
    </div>`;
  }
  const nav = UI.myOrdersNav;
  const openOrder = orders.find((o) => o.id === nav.openId) || orders[0];
  return `
  <div class="container section orders-layout ${nav.openId != null ? "detail-open" : ""}">
    <div class="orders-list">
      <h1 class="page-title">Orders & Help</h1>
      ${orders.map((o) => {
        const meta = STATUS_META[o.status];
        const needsAttn = o.items.some((it) => it.unavailable && !it.resolution);
        return `
        <button class="order-row ${openOrder.id === o.id ? "active" : ""}" data-action="select-order" data-id="${o.id}">
          <div>
            <div class="order-row-id">#${o.id}</div>
            <div class="qk-muted small">${fmtDate(o.createdAt)} · ${o.items.length} item${o.items.length > 1 ? "s" : ""}</div>
          </div>
          <div class="order-row-right">
            ${needsAttn ? '<span class="badge badge-yellow">ACTION NEEDED</span>' : ""}
            ${o.returnRequest && !o.returnRequest.finalized ? `<span class="badge badge-yellow">RETURN IN PROGRESS</span>` : ""}
            <span class="badge badge-${meta.tone}">${meta.label}</span>
          </div>
        </button>`;
      }).join("")}
    </div>
    <div class="order-detail">
      <button class="order-detail-back" data-action="back-to-orders">${ic("chevronLeft")} Back to orders</button>
      ${orderDetailHTML(openOrder)}
    </div>
  </div>`;
}

function orderDetailHTML(order) {
  const partner = findPartner(order.deliveryPartnerId);
  const canCancel = [...PREP_STATUSES, "ready_for_rider"].includes(order.status);
  const canReturn = order.status === "delivered" && (!order.returnRequest || order.returnRequest.status === "rejected");
  return `
  <div class="summary-card">
    <div class="order-detail-head">
      <div>
        <div class="order-row-id">Order #${order.id}</div>
        <div class="qk-muted small">${fmtDateTime(order.createdAt)}</div>
      </div>
      <span class="badge badge-${STATUS_META[order.status].tone}">${STATUS_META[order.status].label}</span>
    </div>
    ${orderStatusBannerHTML(order)}
    <div class="order-detail-timeline">${orderTimelineHTML(order)}</div>
  </div>
  <div class="summary-card">
    <div class="summary-card-title">Items</div>
    ${order.items.map((it, idx) => orderItemRowHTML(order, it, idx)).join("")}
    ${order.comboDiscount > 0 ? `<div class="summary-row summary-row-danger"><span>Combo savings${order.activeCombos && order.activeCombos.length ? ` (${esc(order.activeCombos.join(", "))})` : ""}</span><span class="qk-num">− ${money(order.comboDiscount)}</span></div>` : ""}
    ${order.couponCode ? `<div class="summary-row summary-row-danger"><span>Coupon (${esc(order.couponCode)})</span><span class="qk-num">${order.couponDiscount > 0 ? `− ${money(order.couponDiscount)}` : "Free delivery"}</span></div>` : ""}
    ${order.gst != null ? (() => {
      // order.gst/taxSnapshot only exist on orders placed after tax-mode
      // tracking was added — older orders just skip this line rather than
      // guess at a mode they were never placed under.
      const tax = order.taxSnapshot || State.tax;
      const inclusive = !tax || tax.inclusive !== false;
      return `<div class="summary-row qk-muted"><span>${inclusive ? `Incl. ${esc(tax.name)} (${tax.rate}%)` : `${esc(tax.name)} (${tax.rate}%)`}</span><span class="qk-num">${inclusive ? "" : "+ "}${money(order.gst)}</span></div>`;
    })() : ""}
    <div class="summary-row summary-row-total"><span>Total</span><span class="qk-num">${money(order.total)}</span></div>
  </div>
  <div class="summary-card">
    <div class="summary-row"><span>Method</span><span>${order.fulfillment === "pickup" ? `${ic("store")} Pickup` : `${ic("truck")} Delivery${order.deliverySpeed === "scheduled" ? " · Scheduled" : ""}`}</span></div>
    <div class="summary-row"><span>${order.fulfillment === "pickup" ? "Pickup from" : "Deliver to"}</span></div>
    <div class="qk-muted small">${esc(order.address)}</div>
    ${order.scheduledSlot ? `<div class="summary-row"><span>Delivery time</span><span>${esc(order.scheduledSlot)}</span></div>` : ""}
    ${order.deliveryInstructions ? `<div class="summary-row"><span>Instructions</span></div><div class="qk-muted small">${esc(order.deliveryInstructions)}</div>` : ""}
    <div class="summary-row"><span>Payment</span><span>${esc(order.paymentMethod)}</span></div>
    ${partner ? `<div class="summary-row"><span>Delivery partner</span><span>${esc(partner.name)}</span></div>` : ""}
  </div>
  ${returnRequestHTML(order)}
  ${order.status === "delivered" ? `
    <div class="summary-card">
      ${order.rating ? `<div class="summary-row"><span>Your rating</span><span>${starsHTML(order.rating, true)}</span></div>` : `
        <div class="summary-card-title">Rate your delivery${partner ? ` from ${esc(partner.name)}` : ""}</div>
        <div class="rate-row">${starsHTML(0, false, order.id)}</div>`}
    </div>` : ""}
  ${productRatingsHTML(order)}
  <div class="order-actions">
    <a href="${telHref(State.companyProfile.phone)}" class="btn btn-primary">${ic("phone")} Call support</a>
    ${canCancel ? `<button class="btn btn-outline-danger" data-action="open-cancel-return" data-id="${order.id}" data-kind="cancel">${ic("close")} Cancel</button>` : ""}
    ${canReturn ? `<button class="btn btn-outline" data-action="open-cancel-return" data-id="${order.id}" data-kind="return">Return / Replace</button>` : ""}
  </div>
  ${["delivered", "returned"].includes(order.status) ? `<button class="btn btn-primary btn-block" data-action="open-invoice" data-id="${order.id}">${ic("receipt")} View invoice</button>` : ""}
  <button class="btn btn-outline btn-block" data-action="reorder" data-id="${order.id}">${ic("cart")} Reorder these items</button>
  ${UI.submittedFor === order.id ? `<div class="notice notice-ok">${ic("check")}<span>Request submitted.</span></div>` : ""}
  `;
}

function starsHTML(value, readOnly, orderId, itemId) {
  let out = '<span class="stars">';
  for (let s = 1; s <= 5; s++) {
    if (readOnly) out += `<span class="star ${s <= value ? "filled" : ""}">${ic("star")}</span>`;
    else if (itemId != null) out += `<button class="star star-btn" data-action="rate-item" data-order="${orderId}" data-item="${itemId}" data-rating="${s}">${ic("star")}</button>`;
    else out += `<button class="star star-btn" data-action="rate-order" data-id="${orderId}" data-rating="${s}">${ic("star")}</button>`;
  }
  return out + "</span>";
}

function productRatingsHTML(order) {
  if (order.status !== "delivered") return "";
  const items = order.items.filter((it) => !it.unavailable || it.resolution);
  if (!items.length) return "";
  const ratings = order.itemRatings || {};
  return `
  <div class="summary-card">
    <div class="summary-card-title">Rate your items</div>
    <div class="qk-muted small" style="margin-bottom:10px">Optional — let us know how each item was.</div>
    ${items.map((it) => {
      const r = ratings[it.id] || {};
      const key = `${order.id}-${it.id}`;
      return `
      <div class="item-rating-row">
        <div class="item-rating-name">${esc(it.name)}</div>
        ${starsHTML(r.rating || 0, false, order.id, it.id)}
      </div>
      ${UI.itemFeedbackOpenFor === key ? `
        <form class="item-feedback-form" data-action="save-item-feedback" data-order="${order.id}" data-item="${it.id}">
          <textarea class="input" name="feedback" rows="2" maxlength="300" placeholder="Tell us more (optional)">${esc(r.feedback || "")}</textarea>
          <button type="submit" class="btn btn-outline btn-sm">Save feedback</button>
        </form>` : `
        <button type="button" class="link-btn" data-action="toggle-item-feedback" data-key="${key}">${r.feedback ? "Edit feedback" : "Add feedback"}</button>
        ${r.feedback ? `<div class="qk-muted small">"${esc(r.feedback)}"</div>` : ""}`}
      `;
    }).join("")}
  </div>`;
}

function orderItemRowHTML(order, it, idx) {
  if (it.unavailable && !it.resolution) {
    const catalogItem = findItem(it.id);
    const requestedAlt = it.changeRequest && it.changeRequest.altId
      ? { id: it.changeRequest.altId, name: it.changeRequest.altName, unit: it.changeRequest.altUnit, price: it.changeRequest.altPrice }
      : null;
    const alt = requestedAlt || (catalogItem && catalogItem.altId ? findItem(catalogItem.altId) : null);
    const refundOnly = it.changeRequest && it.changeRequest.refundOnly;
    const altDiff = alt ? (alt.price - it.price) * it.qty : 0;
    return `
    <div class="oos-order-item">
      <div class="oos-order-title">${ic("alert")} ${esc(it.name)} is out of stock</div>
      <div class="qk-muted small">${refundOnly ? "The store confirmed no substitute is available. Choose a refund option:" : requestedAlt ? "The store suggests this replacement — accept it, or choose a refund instead:" : "Sorry about that — this item can't be delivered. Choose how to resolve it:"}</div>
      <div class="oos-order-actions">
        ${alt ? `<button class="btn btn-primary btn-sm" data-action="resolve-item" data-order="${order.id}" data-idx="${idx}" data-res="swap">Swap for ${esc(alt.name)} (${money(alt.price)})${altDiff > 0.01 ? ` — pay ${money(altDiff)} more` : altDiff < -0.01 ? ` — get ${money(-altDiff)} back` : ""}</button>` : ""}
        <button class="btn btn-primary-soft btn-sm" data-action="resolve-item" data-order="${order.id}" data-idx="${idx}" data-res="wallet">Refund ${money(it.price * it.qty * 1.1)} to Wallet — instant, +10% bonus</button>
        <button class="btn btn-outline btn-sm" data-action="resolve-item" data-order="${order.id}" data-idx="${idx}" data-res="original">Refund ${money(it.price * it.qty)} to ${esc(order.paymentMethod)} (3-5 business days)</button>
      </div>
    </div>`;
  }
  const payQty = it.bogo ? Math.ceil(it.qty / 2) : it.qty;
  return `<div class="summary-row"><span>${it.qty} × ${esc(it.name)}${it.bogo ? ` <span class="badge badge-green">BOGO</span>` : ""}${it.resolution === "swap" ? " (swapped)" : it.resolution ? " (refunded)" : ""}</span><span class="qk-num">${money(it.price * payQty)}</span></div>`;
}

