function invoiceHTML(order) {
  const tax = order.taxSnapshot || State.tax;
  const inclusive = !tax || tax.inclusive !== false;
  const lines = invoiceLines(order);
  const itemTotal = lines.reduce((s, l) => s + l.total, 0);
  const taxableTotal = lines.reduce((s, l) => s + l.taxable, 0);
  const gstTotal = lines.reduce((s, l) => s + l.gst, 0);
  const deliveryFee = order.deliveryFee || 0;
  const walletApplied = order.walletApplied || 0;
  const discount = order.discount || 0;
  const comboDiscount = order.comboDiscount || 0;
  const couponDiscount = order.couponDiscount || 0;
  // Exclusive tax is added once on the discounted subtotal (matching exactly
  // how cartTotals computed it at checkout) rather than summed line-by-line —
  // summing per-line tax would overstate it whenever a combo/coupon discount
  // applies, since each line's tax above is calculated pre-discount. This
  // keeps amountDue reconciling exactly with the order's stored total.
  const addedTax = inclusive ? 0 : gstAmount(itemTotal - comboDiscount - couponDiscount, tax);
  const expressCharge = order.expressCharge || 0;
  const invoiceValue = itemTotal - comboDiscount - couponDiscount + addedTax + deliveryFee + expressCharge;
  const amountDue = Math.max(invoiceValue - walletApplied, 0);
  const partner = findPartner(order.deliveryPartnerId);
  const paidStatus = order.status === "delivered" ? "PAID" : order.status === "cancelled" || order.status === "returned" ? "REFUNDED / VOID" : "PENDING";
  return `
  <div class="inv">
    <div class="inv-top">
      <div class="inv-seller">
        <img src="${State.siteCustomization.branding.logoUrl}" alt="" />
        <div>
          <div class="inv-company">${esc(State.companyProfile.name)}</div>
          <div>Trading as ${esc(State.companyProfile.tradingAs)}</div>
          <div>${esc(State.companyProfile.address1)}</div>
          <div>${esc(State.companyProfile.address2)}</div>
          <div>UEN: ${esc(State.companyProfile.uen)} · GST Reg. No: ${esc(State.companyProfile.gstReg)}</div>
          <div>SFA Licence No: ${esc(State.companyProfile.sfaLicence)}</div>
        </div>
      </div>
      <div class="inv-title">
        <div class="inv-title-main">TAX INVOICE</div>
        <div>${esc(State.companyProfile.phone)}</div>
        <div>${esc(State.companyProfile.email)}</div>
      </div>
    </div>
    <div class="inv-meta">
      <div><div><b>Invoice No.:</b> ${esc(order.invoiceNo || `INV-${order.id}`)}</div><div><b>Order No.:</b> ${esc(order.id)}</div></div>
      <div><div><b>Invoice Date:</b> ${fmtDate(order.createdAt)}</div><div><b>Place of Supply:</b> Singapore</div></div>
    </div>
    <div class="inv-parties">
      <div><div class="inv-col-title">Bill To</div><div>${esc(order.contactName || order.customerName)}</div>${order.contactMobile ? `<div>${fmtMobile(order.contactMobile)}</div>` : ""}</div>
      <div><div class="inv-col-title">Ship To${order.addressType ? ` (${esc(order.addressType)})` : ""}</div><div>${esc(order.contactName || order.customerName)}</div><div>${esc(order.address)}</div>${order.contactMobile ? `<div>${fmtMobile(order.contactMobile)}</div>` : ""}</div>
    </div>
    <div class="inv-table-wrap">
      <table class="inv-table">
        <thead><tr><th>SN</th><th>Item &amp; Description</th><th>Unit</th><th>HS Code</th><th class="r">Qty</th><th class="r">Rate</th><th class="r">Taxable</th><th class="r">GST ${tax.rate}%</th><th class="r">Amount</th></tr></thead>
        <tbody>
          ${lines.map((l) => `<tr><td>${l.sn}</td><td>${esc(l.name)}${l.note ? ` <span class="qk-muted">(${l.note})</span>` : ""}</td><td>${esc(l.unit)}</td><td>${esc(l.hs)}</td><td class="r">${l.qty}</td><td class="r">${money(l.rate)}</td><td class="r">${money(l.taxable)}</td><td class="r">${money(l.gst)}</td><td class="r"><b>${money(l.total)}</b></td></tr>`).join("")}
        </tbody>
        <tfoot><tr><td colspan="6"><b>Total</b></td><td class="r"><b>${money(taxableTotal)}</b></td><td class="r"><b>${money(gstTotal)}</b></td><td class="r"><b>${money(itemTotal)}</b></td></tr></tfoot>
      </table>
    </div>
    <div class="inv-totals">
      <div class="inv-totals-box">
        <div class="row"><span>Item total (${inclusive ? "incl." : "excl."} GST)</span><span>${money(itemTotal)}</span></div>
        ${discount > 0 ? `<div class="row"><span>Savings applied</span><span>− ${money(discount)}</span></div>` : ""}
        ${comboDiscount > 0 ? `<div class="row"><span>Combo savings${order.activeCombos && order.activeCombos.length ? ` (${esc(order.activeCombos.join(", "))})` : ""}</span><span>− ${money(comboDiscount)}</span></div>` : ""}
        ${couponDiscount > 0 ? `<div class="row"><span>Coupon discount${order.couponCode ? ` (${esc(order.couponCode)})` : ""}</span><span>− ${money(couponDiscount)}</span></div>` : ""}
        ${order.couponFreeShip ? `<div class="row"><span>Free delivery${order.couponCode ? ` (${esc(order.couponCode)})` : ""}</span><span>Applied</span></div>` : ""}
        ${!inclusive ? `<div class="row"><span>${esc(tax.name)} (${tax.rate}%)</span><span>+ ${money(addedTax)}</span></div>` : ""}
        <div class="row"><span>Delivery charges</span><span>${deliveryFee > 0 ? money(deliveryFee) : "FREE"}</span></div>
        ${expressCharge > 0 ? `<div class="row"><span>Express delivery charge</span><span>${money(expressCharge)}</span></div>` : ""}
        <div class="row border-t"><b>Invoice value</b><b>${money(invoiceValue)}</b></div>
        ${walletApplied > 0 ? `<div class="row"><span>Paid from MyShopza Wallet</span><span>− ${money(walletApplied)}</span></div>` : ""}
        <div class="row border-t2"><b>Amount payable</b><b>${money(amountDue)}</b></div>
        ${inclusive ? `<div class="row muted"><span>Of which GST (${tax.rate}%)</span><span>${money(gstTotal)}</span></div>` : ""}
      </div>
    </div>
    <div class="inv-bottom">
      <div><div class="inv-col-title">Payment</div><div>Method: ${esc(order.paymentMethod)}</div><div>Status: ${paidStatus}</div><div>Order status: ${STATUS_META[order.status].label}</div></div>
      <div><div class="inv-col-title">Fulfilment</div><div>Delivered by: ${esc(State.companyProfile.name)}</div>${partner ? `<div>Delivery partner: ${esc(partner.name)} (${esc(partner.code)})</div>` : ""}<div>Order placed: ${fmtDateTime(order.createdAt)}</div></div>
    </div>
    <div class="inv-legal">
      <div>All prices are quoted in Singapore Dollars and are ${inclusive ? `inclusive of ${tax.rate}% GST` : `exclusive of GST — ${tax.rate}% GST is added at checkout`}, as required under the Goods and Services Tax Act.</div>
      <div>This is a computer-generated invoice and does not require a signature.</div>
      <div>Questions about this invoice? Contact ${esc(State.companyProfile.email)} or ${esc(State.companyProfile.phone)}.</div>
      <div class="italic">Prototype invoice — company registration numbers shown are placeholders.</div>
    </div>
  </div>`;
}

function printInvoiceNow(order) {
  const node = document.getElementById("qk-invoice");
  if (!node) return;
  const title = `Invoice ${order.invoiceNo || order.id} — ${State.companyProfile.name}`;
  const css = `
    body{font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#000;margin:28px;line-height:1.4;}
    *{box-sizing:border-box;}
    table{width:100%;border-collapse:collapse;} th,td{padding:5px 6px;text-align:left;}
    .r{text-align:right;} .inv-top,.inv-meta,.inv-parties,.inv-bottom,.inv-totals{display:flex;justify-content:space-between;gap:12px;}
    .inv-seller{display:flex;gap:8px;} .inv-seller img{height:36px;width:36px;object-fit:contain;}
    .inv-title{text-align:right;} .inv-title-main{font-weight:700;letter-spacing:.04em;font-size:11px;}
    .inv-company{font-weight:700;font-size:11px;} .inv-col-title{font-weight:700;margin-bottom:2px;}
    .inv-top,.inv-meta{border-bottom:1px solid #ccc;padding-bottom:8px;margin-bottom:8px;}
    .inv-parties{border-bottom:1px solid #ccc;padding-bottom:8px;margin-bottom:8px;}
    thead tr{background:#efefef;} tfoot tr{background:#f6f6f6;} tbody tr{border-bottom:1px solid #e4e4e4;}
    .inv-totals{justify-content:flex-end;} .inv-totals-box{width:260px;}
    .row{display:flex;justify-content:space-between;padding:2px 0;} .border-t{border-top:1px solid #ccc;margin-top:2px;padding-top:4px;}
    .border-t2{border-top:1px solid #666;margin-top:2px;padding-top:4px;} .muted{color:#444;}
    .inv-bottom{border-top:1px solid #ccc;padding-top:8px;margin-top:8px;} .inv-legal{border-top:1px solid #ccc;padding-top:8px;margin-top:8px;color:#555;}
    .italic{font-style:italic;}
    @media print{body{margin:0;} @page{margin:14mm;}}
  `;
  const doc = `<!doctype html><html><head><meta charset="utf-8" /><title>${title}</title><style>${css}</style></head><body>${node.innerHTML}</body></html>`;
  const frame = document.createElement("iframe");
  frame.setAttribute("aria-hidden", "true");
  frame.style.cssText = "position:fixed;left:-10000px;top:0;width:820px;height:1160px;border:0;";
  document.body.appendChild(frame);
  const cleanUp = () => { if (frame.parentNode) frame.parentNode.removeChild(frame); };
  let started = false;
  const start = () => {
    if (started) return;
    started = true;
    const win = frame.contentWindow;
    setTimeout(() => {
      try { win.focus(); win.print(); } catch (e) {}
      win.addEventListener && win.addEventListener("afterprint", cleanUp);
      setTimeout(cleanUp, 60000);
    }, 350);
  };
  frame.onload = start;
  const fdoc = frame.contentWindow.document;
  fdoc.open(); fdoc.write(doc); fdoc.close();
  if (fdoc.readyState === "complete") start();
}

