/* ---------------- Admin shell ---------------- */
// The admin sidebar reuses PERMISSION_SCREENS as its single source of truth —
// one entry per screen, one implementation per screen. Which of these a given
// user actually sees is filtered live by their effective permissions below,
// so Super Admin and a Store Manager render the exact same nav/body code,
// just with a different visible slice and different Viewing scope.
const ADMIN_TABS = PERMISSION_SCREENS;
// Tabs whose data is meaningfully split per branch — these respect the
// Viewing scope switcher in the topbar. Everything else (catalog, categories,
// tax, promotions, coupons) stays network-wide, matching the shared-catalog model.
const BRANCH_SCOPED_TABS = ["dashboard", "orders", "partners", "inventory"];
function visibleAdminTabs(user) {
  return ADMIN_TABS.filter((t) => canView(user, t.key));
}
function viewAdminShell() {
  const user = currentUser();
  if (!user) return viewLogin();
  const tabs = visibleAdminTabs(user);
  if (!tabs.find((t) => t.key === UI.adminTab)) UI.adminTab = tabs[0] ? tabs[0].key : null;
  const role = findRole(user.roleId);
  const myStores = userStoreIds(user).map(findBranch).filter(Boolean);
  const eyebrow = isSuperAdmin(user) ? "Super Admin · Admin panel"
    : `${role ? role.name : "Admin"}${myStores.length === 1 ? ` · ${myStores[0].name}` : myStores.length > 1 ? ` · ${myStores.length} stores` : " · No store assigned"}`;
  const scopeIds = userStoreIds(user);
  const showScopeSwitcher = BRANCH_SCOPED_TABS.includes(UI.adminTab) && (isSuperAdmin(user) || scopeIds.length > 1);
  return `
  <div class="dash-shell">
    <aside class="dash-sidebar">
      <div class="dash-brand"><span class="brand-tile"><img src="${State.siteCustomization.branding.logoUrl}" alt="" /></span><span class="brand-word">MyShopza</span></div>
      <div class="dash-eyebrow">${esc(eyebrow)}</div>
      <nav class="dash-nav">${adminNavHTML(tabs)}</nav>
      <button class="dash-logout" data-action="logout">${ic("logout")}<span>Logout</span></button>
    </aside>
    <div class="dash-content">
      <div class="dash-topbar">
        <h1>${UI.adminTab ? adminPageTitle(UI.adminTab) : "Admin"}</h1>
        ${showScopeSwitcher ? `
          <label class="branch-scope"><span class="field-label">Viewing</span>
            <select class="input" data-action="admin-branch-scope">
              <option value="all" ${UI.adminBranchScope === "all" ? "selected" : ""}>${isSuperAdmin(user) ? "All branches (Super Admin)" : "All my stores"}</option>
              ${(isSuperAdmin(user) ? State.branches : scopeIds.map(findBranch).filter(Boolean)).map((b) => `<option value="${b.id}" ${String(UI.adminBranchScope) === String(b.id) ? "selected" : ""}>${esc(b.name)}</option>`).join("")}
            </select>
          </label>` : ""}
      </div>
      <div class="dash-body">${UI.adminTab ? adminTabContent(user) : `<div class="empty-state"><div class="empty-title">No screens available</div><div class="empty-hint">Ask a Super Admin to grant your account access under Admin ▸ Users.</div></div>`}</div>
    </div>
  </div>
  ${modalLayer()}
  <div id="toastHolder" class="toast-holder"></div>`;
}

function adminTabContent(user) {
  if (!canView(user, UI.adminTab)) return `<div class="empty-state"><div class="empty-title">You don't have access to this screen</div></div>`;
  switch (UI.adminTab) {
    case "stores": return adminBranches();
    case "users": return adminUsers();
    case "customers": return adminCustomersV2(); // Round 3
    case "brands": return adminBrands();
    case "catalog": return adminCatalogV2(); // Round 3
    case "categories": return adminCategories();
    case "homeScreen": return adminHomeScreen();
    case "orders": return adminOrdersV2(); // Round 3
    case "reports": return adminReports();
    case "partners": return adminPartners();
    case "tax": return adminBusinessSettings();
    case "promotions": return adminPromotions();
    case "coupons": return adminCoupons();
    // 2026-09 screens (quickkart-2026-09.js)
    case "inventory": return adminInventoryV2();
    case "suppliers": return adminSuppliers();
    case "slots": return adminSlots();
    case "routes": return adminRoutesTBD();
    case "notifications": return adminNotifications();
    default: return adminDashboard();
  }
}
// Resolves the topbar's Viewing scope to the set of branch ids the current
// screen should be filtered to: null means "no restriction" (Super Admin
// looking at the whole network), an array is the exact branch ids to show —
// for a store-scoped user this is always a subset of (usually exactly) their
// own assigned stores, never anyone else's.
function scopedBranchIds() {
  const user = currentUser();
  if (!user) return [];
  if (isSuperAdmin(user)) {
    if (UI.adminBranchScope === "all") return null;
    const id = Number(UI.adminBranchScope);
    return findBranch(id) ? [id] : null;
  }
  const mine = userStoreIds(user).filter((id) => findBranch(id));
  if (mine.length <= 1) return mine;
  if (UI.adminBranchScope === "all") return mine;
  const id = Number(UI.adminBranchScope);
  return mine.includes(id) ? [id] : mine;
}

function adminDashboard() {
  const branchIds = scopedBranchIds();
  const now = new Date();
  const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const startOfWeek = startOfDay - now.getDay() * 86400000;
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
  const yesterdayStart = startOfDay - 86400000;
  const lastWeekStart = startOfWeek - 7 * 86400000;
  const scopedOrders = branchIds ? State.orders.filter((o) => branchIds.includes(o.branchId)) : State.orders;
  const billable = scopedOrders.filter((o) => o.status !== "cancelled");
  const sumBetween = (from, to) => billable.filter((o) => o.createdAt >= from && (to == null || o.createdAt < to)).reduce((s, o) => s + o.total, 0);
  const countSince = (ts) => billable.filter((o) => o.createdAt >= ts).length;
  const todaySales = sumBetween(startOfDay), yesterdaySales = sumBetween(yesterdayStart, startOfDay);
  const todayTrend = yesterdaySales > 0 ? Math.round(((todaySales - yesterdaySales) / yesterdaySales) * 100) : null;
  const weekSales = sumBetween(startOfWeek), lastWeekSales = sumBetween(lastWeekStart, startOfWeek);
  const weekTrend = lastWeekSales > 0 ? Math.round(((weekSales - lastWeekSales) / lastWeekSales) * 100) : null;
  const pipeline = scopedOrders.filter((o) => !TERMINAL_STATUSES.includes(o.status)).sort((a, b) => b.createdAt - a.createdAt);
  const itemSales = {};
  billable.forEach((o) => o.items.forEach((it) => { itemSales[it.name] = (itemSales[it.name] || 0) + it.qty; }));
  const topSellers = Object.entries(itemSales).sort((a, b) => b[1] - a[1]).slice(0, 5);
  const maxSold = topSellers.length ? topSellers[0][1] : 1;
  const trendHTML = (pct) => pct == null ? "" : `<span class="trend ${pct >= 0 ? "up" : "down"}">${pct >= 0 ? "▲" : "▼"} ${Math.abs(pct)}%</span>`;
  // Network-wide view (no branch restriction): the classic Super Admin
  // dashboard — top sellers + the shared catalog's out-of-stock list.
  // Restricted to one or more specific stores: swap in the store-operator
  // view — riders on hand + THIS store's effective (per-branch) stock,
  // which is what a Store Manager actually needs day to day.
  const secondaryHTML = !branchIds ? (() => {
    const lowStock = State.items.filter((i) => !customerItemAvailable(i));
    return `
    <div class="dash-grid-2">
      <div class="summary-card">
        <div class="summary-card-title">Stock alerts</div>
        ${State.branches.map((b) => { const low = State.items.filter((i) => stockStatus(b.id, i).key === "low").length; const out = State.items.filter((i) => ["out", "negative"].includes(stockStatus(b.id, i).key)).length; return `<div class="row"><span>${esc(b.name)}</span><span><span class="badge badge-yellow-soft">${low} low</span> <span class="badge badge-red-soft">${out} out</span></span></div>`; }).join("")}
        <button class="link-btn small" data-action="admin-tab" data-tab="inventory">Open Masters › Stock →</button>
      </div>
      <div class="summary-card">
        <div class="summary-card-title">Out of stock for customers ${lowStock.length ? `<span class="badge badge-red-soft">${lowStock.length}</span>` : ""}</div>
        ${lowStock.length ? lowStock.map((i) => `<div class="row"><span>${esc(i.name)}</span><span class="badge badge-red-soft">Out</span></div>`).join("") : `<div class="qk-muted small">Everything is in stock.</div>`}
      </div>
    </div>`;
  })() : (() => {
    const riders = State.partners.filter((p) => branchIds.includes(p.branchId));
    const availableRiders = riders.filter((r) => riderIsReady(r.id)).length;
    const activeDeliveries = riders.filter((r) => riderIsBusy(r.id)).length;
    const lowStock = branchIds.reduce((sum, bid) => sum + State.items.filter((i) => stockStatus(bid, i).key === "low").length, 0);
    const outOfStock = branchIds.reduce((sum, bid) => sum + State.items.filter((i) => ["out", "negative", "off"].includes(stockStatus(bid, i).key)).length, 0);
    return `
    <div class="dash-grid-2">
      <div class="summary-card">
        <div class="summary-card-title">Riders</div>
        <div class="row"><span>Available now</span><span class="badge badge-green-soft">${availableRiders}</span></div>
        <div class="row"><span>Active deliveries</span><span class="badge badge-blue-soft">${activeDeliveries}</span></div>
        <div class="row"><span>Total assigned</span><span>${riders.length}</span></div>
      </div>
      <div class="summary-card">
        <div class="summary-card-title">Stock</div>
        <div class="row"><span>Low stock</span><span class="badge badge-${lowStock ? "yellow-soft" : "green-soft"}">${lowStock}</span></div>
        <div class="row"><span>Out of stock</span><span class="badge badge-${outOfStock ? "red-soft" : "green-soft"}">${outOfStock}</span></div>
      </div>
    </div>`;
  })();
  return `
  <div class="stat-grid">
    <div class="stat-card"><div class="stat-label">Today's sales</div><div class="stat-value">${money(todaySales)}</div><div class="stat-sub">${trendHTML(todayTrend)}<span>${countSince(startOfDay)} orders</span></div></div>
    <div class="stat-card"><div class="stat-label">This week</div><div class="stat-value">${money(weekSales)}</div><div class="stat-sub">${trendHTML(weekTrend)}<span>${countSince(startOfWeek)} orders</span></div></div>
    <div class="stat-card"><div class="stat-label">This month</div><div class="stat-value">${money(sumBetween(startOfMonth))}</div><div class="stat-sub"><span>${countSince(startOfMonth)} orders</span></div></div>
    <div class="stat-card"><div class="stat-label">In pipeline</div><div class="stat-value">${pipeline.length}</div><div class="stat-sub"><span>Not yet delivered, cancelled, or returned</span></div></div>
  </div>
  ${dashboardInsightsHTML(scopedOrders)}
  ${secondaryHTML}
  <div class="summary-card">
    <div class="summary-card-title">Orders in pipeline ${pipeline.length ? `<span class="badge badge-blue-soft">${pipeline.length}</span>` : ""}</div>
    ${pipeline.length === 0 ? `<div class="qk-muted small">Nothing in the pipeline right now.</div>` : pipeline.slice(0, 8).map((o) => `
      <div class="row"><span>#${o.id} · ${esc(o.customerName)}</span><span>${money(o.total)} <span class="badge badge-${STATUS_META[o.status].tone}-soft">${STATUS_META[o.status].label}</span></span></div>`).join("")}
  </div>`;
}

// One implementation for both audiences: Super Admin gets the full network
// grid (add/delete, every field editable); a store-scoped user gets just
// their own assigned store(s), editable only for hours/open-closed — name,
// coordinates and delivery radius stay Super-Admin-only because they're
// network-routing data, not a single store's own settings (see storeSettingsCard).
function adminBranches() {
  const user = currentUser();
  if (isSuperAdmin(user)) {
    return `
    <button class="btn btn-primary" data-action="new-branch">${ic("plus")} Add branch</button>
    <div class="qk-muted small" style="margin:10px 0">Each branch owns its own orders and rider pool, and draws from the shared network-wide catalog.</div>
    <div class="partner-grid">
      ${State.branches.map((b) => {
        const riders = branchRiders(b.id);
        const orders = State.orders.filter((o) => o.branchId === b.id);
        const activeOrders = orders.filter((o) => !TERMINAL_STATUSES.includes(o.status));
        const managers = usersForBranch(b.id);
        return `
        <div class="partner-card">
          <div class="partner-card-top">
            <div><span class="status-dot ${b.active ? "on" : ""}"></span><span class="partner-name">${esc(b.name)}</span>
              <div class="qk-muted small">${esc(b.area)}</div>
              <div class="qk-muted small">Radius ${b.radiusKm} km · ${esc(b.hoursOpen)}–${esc(b.hoursClose)}</div>
              <div class="qk-muted small">${ic("user")} ${managers.length ? `Manager${managers.length > 1 ? "s" : ""}: ${managers.map((m) => esc(m.name)).join(", ")}` : "No manager assigned"}</div>
              ${b.pickupAvailable ? `<div class="qk-muted small">${ic("store")} Pickup: ${esc(b.pickupAddress || "No pickup address set")}</div>` : ""}
            </div>
            <div class="partner-card-actions">
              <span class="badge badge-${b.active ? "green" : "red"}">${b.active ? "Active" : "Inactive"}</span>
              ${b.pickupAvailable ? `<span class="badge badge-blue-soft">Pickup</span>` : ""}
              <button class="icon-btn" data-action="edit-branch" data-id="${b.id}">${ic("edit")}</button>
              <button class="icon-btn icon-btn-danger" data-action="delete-branch" data-id="${b.id}">${ic("trash")}</button>
            </div>
          </div>
          <div class="partner-stats">
            <div><div class="stat-value-sm">${riders.length}</div><div class="qk-muted small">Riders</div></div>
            <div><div class="stat-value-sm">${activeOrders.length}</div><div class="qk-muted small">Active orders</div></div>
            <div><div class="stat-value-sm">${orders.length}</div><div class="qk-muted small">Total orders</div></div>
          </div>
        </div>`;
      }).join("")}
      ${State.branches.length === 0 ? `<div class="empty-state"><div class="empty-title">No branches yet</div><div class="empty-hint">Add one to start routing orders and riders by location.</div></div>` : ""}
    </div>`;
  }
  const editable = canEdit(user, "stores");
  const myBranches = userStoreIds(user).map(findBranch).filter(Boolean);
  if (myBranches.length === 0) {
    return `<div class="empty-state"><div class="empty-title">No store assigned</div><div class="empty-hint">Ask a Super Admin to assign a store to your account under Admin ▸ Users.</div></div>`;
  }
  return `
  <div class="qk-muted small" style="margin:0 0 12px">${editable ? "Area, coordinates, and service radius are set by Super Admin (they affect which customers get routed here) — you can update hours and open/closed status." : "Read-only — ask a Super Admin for edit access under Admin ▸ Users."}</div>
  <div style="display:flex;flex-wrap:wrap;gap:16px">
    ${myBranches.map((b) => storeSettingsCard(b, editable)).join("")}
  </div>`;
}
// The single "own store" settings view — used both for a store-scoped user's
// Stores screen and (identically) reused nowhere else, so there is exactly
// one place that renders a store's operational settings.
function storeSettingsCard(branch, editable) {
  return `
  <div class="summary-card" style="max-width:420px;flex:1 1 360px">
    <div class="summary-card-title">${esc(branch.name)} <span class="badge badge-${branch.active ? "green" : "red"}" style="margin-left:8px">${branch.active ? "Active" : "Inactive"}</span></div>
    <div class="row"><span>Area</span><span>${esc(branch.area)}</span></div>
    <div class="row"><span>Service radius</span><span>${branch.radiusKm} km</span></div>
    ${editable ? `
    <form data-action="save-store-hours" data-branch="${branch.id}">
      <div class="field-grid-2">
        <label class="field"><span class="field-label">Opens</span><input class="input" type="time" name="hoursOpen" value="${esc(branch.hoursOpen)}" /></label>
        <label class="field"><span class="field-label">Closes</span><input class="input" type="time" name="hoursClose" value="${esc(branch.hoursClose)}" /></label>
      </div>
      <label class="stock-toggle-lg"><input type="checkbox" name="active" ${branch.active ? "checked" : ""} /><span>Store open — accepting new orders</span></label>
      <button type="submit" class="btn btn-primary btn-block" style="margin-top:12px">Save store settings</button>
    </form>` : `<div class="row"><span>Hours</span><span>${esc(branch.hoursOpen)}–${esc(branch.hoursClose)}</span></div>`}
  </div>`;
}

// Users screen — Super Admin's control center for the whole RBAC system:
// create/edit/deactivate users, assign a role/profile + store(s), and (via
// the Roles sub-tab) tune what the Store Manager profile grants by default.
// A user with delegated Users=Edit access sees the same screen, minus the
// ability to hand out the Super Admin role itself (see userFormModal).
function adminUsers() {
  const editable = canEdit(currentUser(), "users");
  const sub = UI.usersSubTab || "users";
  return `
  <div class="pill-row">
    <button class="pill ${sub === "users" ? "active" : ""}" data-action="users-subtab" data-tab="users">Users</button>
    <button class="pill ${sub === "roles" ? "active" : ""}" data-action="users-subtab" data-tab="roles">Roles &amp; Permissions</button>
  </div>
  ${sub === "roles" ? adminRolesV2(editable) : adminUsersListV2(editable)}`;
}
function adminUsersList(editable) {
  return `
  ${editable ? `<button class="btn btn-primary" data-action="new-user">${ic("plus")} Add user</button>` : ""}
  <div class="admin-table" style="margin-top:12px">
    ${State.users.map((u) => {
      const role = findRole(u.roleId);
      const stores = userStoreIds(u).map(findBranch).filter(Boolean);
      const storeLabel = isSuperAdmin(u) ? "All stores" : stores.length ? stores.map((b) => b.name).join(", ") : "Unassigned";
      return `
      <div class="admin-row">
        <div class="admin-row-info">
          <div class="admin-row-name">${esc(u.name)}</div>
          <div class="qk-muted small">${esc(u.email || "—")}${u.mobile ? " · " + fmtMobile(u.mobile) : ""}</div>
        </div>
        <span class="badge badge-blue-soft">${esc(role ? role.name : "—")}</span>
        <span class="badge badge-gray-soft">${esc(storeLabel)}</span>
        <span class="badge badge-${u.active === false ? "red" : "green"}">${u.active === false ? "Inactive" : "Active"}</span>
        ${editable ? `
        <button class="icon-btn" data-action="edit-user" data-id="${u.id}">${ic("edit")}</button>
        <button class="icon-btn icon-btn-danger" data-action="delete-user" data-id="${u.id}">${ic("trash")}</button>` : ""}
      </div>`;
    }).join("")}
    ${State.users.length === 0 ? `<div class="empty-state"><div class="empty-title">No users yet</div></div>` : ""}
  </div>`;
}
// The Store Manager profile's default permissions — the template new Store
// Manager users are pre-filled from (see userFormModal), independently
// overridable per user. Super Admin is shown for context but is locked:
// it always resolves to full access and never runs through this table.
function adminRoles(editable) {
  const smRole = findRole(ROLE_STORE_MANAGER);
  return `
  <div class="summary-card" style="max-width:640px">
    <div class="summary-card-title">Super Admin</div>
    <div class="qk-muted small">Locked — always has full access to every screen, across every store. Can't be restricted by this permission system.</div>
  </div>
  <div class="summary-card" style="max-width:640px;margin-top:16px">
    <div class="summary-card-title">Store Manager — default permissions</div>
    <div class="qk-muted small" style="margin-bottom:10px">New Store Manager users start with these defaults. An individual user's permissions can still be overridden from their own user record.</div>
    <form data-action="save-role-permissions" data-role="${ROLE_STORE_MANAGER}">
      <div class="perm-grid">
        ${PERMISSION_SCREENS.map((s) => `<div class="perm-row"><span>${s.label}</span>${permissionSelect(s.key, smRole.permissions[s.key] || "none", s.editable, !editable, "role")}</div>`).join("")}
      </div>
      ${editable ? `<button type="submit" class="btn btn-primary" style="margin-top:14px">Save defaults</button>` : ""}
    </form>
  </div>`;
}
function permissionSelect(screenKey, selected, editableAllowed, disabled, scope) {
  const levels = editableAllowed ? ["none", "view", "edit"] : ["none", "view"];
  const val = levels.includes(selected) ? selected : "none";
  const label = { none: "None", view: "View", edit: "Edit" };
  return `
  <div class="perm-toggle ${disabled ? "is-disabled" : ""}">
    ${levels.map((l) => {
      const id = `perm_${scope || "x"}_${screenKey}_${l}`;
      return `<input class="perm-radio" type="radio" id="${id}" name="perm_${screenKey}" value="${l}" ${val === l ? "checked" : ""} ${disabled ? "disabled" : ""} />
      <label class="perm-seg seg-${l}" for="${id}">${label[l]}</label>`;
    }).join("")}
  </div>`;
}

function adminCatalog() {
  const editable = canEdit(currentUser(), "catalog");
  return `
  <div class="admin-toolbar">
    <div class="search-box"><span>${ic("search")}</span><input class="input" value="${esc(UI.adminQuery)}" oninput="onAdminSearch(this.value)" placeholder="Search by name, brand or SKU..." /></div>
    <div class="filter-pill-row">
      ${editable ? `<button class="btn btn-primary btn-sm" data-action="new-item">${ic("plus")} Add product</button><button class="btn btn-outline btn-sm" data-action="open-import" data-entity="products">${ic("upload")} Import</button>` : ""}
      ${exportButtonsHTML("catalog")}
    </div>
  </div>
  <div class="qk-muted small" style="margin:-4px 0 10px">The product master, shared by every store. Quantities live per store in Masters ▸ Stock.</div>
  <div class="pill-row">
    <button class="pill ${UI.adminCatFilter === "All" ? "active" : ""}" data-action="admin-cat-filter" data-cat="All">All</button>
    ${State.categories.map((c) => `<button class="pill ${UI.adminCatFilter === c.name ? "active" : ""}" data-action="admin-cat-filter" data-cat="${esc(c.name)}">${esc(c.name)}</button>`).join("")}
  </div>
  <div id="adminList" class="admin-table">${adminCatalogRows()}</div>`;
}
function adminCatalogRows() {
  const editable = canEdit(currentUser(), "catalog");
  const q = UI.adminQuery.toLowerCase();
  const items = State.items
    .filter((i) => !q || i.name.toLowerCase().includes(q) || (i.brand || "").toLowerCase().includes(q) || (i.sku || "").toLowerCase().includes(q))
    .filter((i) => UI.adminCatFilter === "All" || i.cat === UI.adminCatFilter);
  return `
    ${items.map((item) => `
      <div class="admin-row">
        <img src="${item.image}" class="admin-row-img" alt="" />
        <div class="admin-row-info">
          <div class="admin-row-name">${esc(item.name)}</div>
          <div class="qk-muted small">${esc(item.sku || "")} · ${item.brand ? `${esc(item.brand)} · ` : ""}${esc(item.cat)} · ${esc(supplierName(item.supplierId))}</div>
          <div class="qk-muted small">Price <b>${money(item.price)}</b> · Cost ${money(item.costPrice || 0)} · Margin ${item.price ? Math.round(((item.price - (item.costPrice || 0)) / item.price) * 100) : 0}% ${!item.stock ? '<span class="badge badge-red-soft">Not selling</span>' : !customerItemAvailable(item) ? '<span class="badge badge-red-soft">Out of stock everywhere</span>' : ""}</div>
        </div>
        ${editable ? `
        <label class="stock-toggle"><input type="checkbox" ${item.stock ? "checked" : ""} data-action="toggle-stock" data-id="${item.id}" /><span>${item.stock ? "In" : "Out"}</span></label>
        <button class="icon-btn" data-action="edit-item" data-id="${item.id}" aria-label="Edit">${ic("edit")}</button>
        <button class="icon-btn icon-btn-danger" data-action="delete-item" data-id="${item.id}" aria-label="Delete">${ic("trash")}</button>` : `
        <span class="badge badge-${item.stock ? "green" : "red"}">${item.stock ? "In" : "Out"}</span>`}
      </div>`).join("")}
    ${items.length === 0 ? `<div class="empty-state"><div class="empty-title">No items match</div></div>` : ""}`;
}

// ---------- Customers (Super Admin visibility — view-only) ----------
// There is no separate customer-accounts table in this prototype (see the
// login flow: a customer session is just a free-text name, no password, no
// stored identity). So the customer list is derived by grouping existing
// orders by customerName — the same join `myOrders()` already relies on for
// a shopper's own order history. Nothing is persisted here; it's a read-only
// projection, recomputed on every render straight from State.orders.
function customersFromOrders() {
  const map = new Map();
  State.orders.forEach((o) => {
    const key = o.customerName || "Unknown";
    if (!map.has(key)) map.set(key, { key, name: key, mobile: "", orders: [] });
    const c = map.get(key);
    c.orders.push(o);
    if (!c.mobile && o.contactMobile) c.mobile = o.contactMobile;
  });
  return [...map.values()].map((c) => {
    const orders = c.orders.slice().sort((a, b) => b.createdAt - a.createdAt);
    const billable = orders.filter((o) => o.status !== "cancelled");
    return {
      ...c,
      orders,
      orderCount: orders.length,
      totalSpent: billable.reduce((s, o) => s + o.total, 0),
      firstOrderAt: orders.reduce((min, o) => Math.min(min, o.createdAt), orders[0].createdAt),
      lastOrderAt: orders[0].createdAt,
    };
  }).sort((a, b) => b.lastOrderAt - a.lastOrderAt);
}
function adminCustomers() {
  return `
  <div class="admin-toolbar">
    <div class="search-box"><span>${ic("search")}</span><input class="input" value="${esc(UI.adminCustomerQuery || "")}" oninput="onAdminCustomerSearch(this.value)" placeholder="Search by name or mobile..." /></div>
    ${exportButtonsHTML("customers")}
  </div>
  <div id="adminCustomersList" class="admin-orders-list">${adminCustomersRows()}</div>`;
}
function adminCustomersRows() {
  const q = (UI.adminCustomerQuery || "").trim().toLowerCase();
  const customers = customersFromOrders().filter((c) => !q || c.name.toLowerCase().includes(q) || (c.mobile && c.mobile.includes(q)));
  if (!customers.length) return `<div class="empty-state"><div class="empty-title">No customers ${q ? "match your search" : "yet"}</div>${q ? "" : '<div class="empty-hint">Customers appear here once someone places their first order.</div>'}</div>`;
  return customers.map((c) => customerRow(c)).join("");
}
// One full-width row per customer (matches adminOrders()'s list, not the
// partner tile grid) — click the row to expand their order history inline.
function customerRow(c) {
  const open = UI.openCustomerKey === c.key;
  return `
  <div class="admin-order-card">
    <button class="admin-order-head" data-action="toggle-customer" data-key="${esc(c.key)}">
      <div><div class="order-row-id">${esc(c.name)}</div><div class="qk-muted small">${c.mobile ? fmtMobile(c.mobile) : "No mobile on file"} · Customer since ${fmtDate(c.firstOrderAt)}</div></div>
      <div class="order-row-right">
        <span class="qk-muted small">${c.orderCount} order${c.orderCount > 1 ? "s" : ""}</span>
        <span class="qk-num">${money(c.totalSpent)}</span>
        <span class="badge badge-green-soft">Active</span>
      </div>
    </button>
    ${open ? `
    <div class="admin-order-body">
      <div class="row"><span>Wallet balance</span><span class="qk-num">${money(State.wallet)}</span></div>
      <div class="qk-muted small" style="margin:-4px 0 10px">View-only. This prototype tracks one demo wallet per browser, not a separate balance per customer.</div>
      <div class="qk-muted small" style="margin-bottom:2px">Order history</div>
      ${c.orders.map((o) => `
        <div class="row"><span>#${o.id} · ${fmtDate(o.createdAt)} <span class="badge badge-${STATUS_META[o.status].tone}-soft">${STATUS_META[o.status].label}</span></span><span class="qk-num">${money(o.total)}</span></div>
      `).join("")}
    </div>` : ""}
  </div>`;
}

