// ---------- Generic tile-list editor (Hero baseline slides, Category Tiles,
// Offer Tiles, Trust Strip) ----------
// One modal object doubles as both screens: editingTileId === null shows the
// list; setting it (or "new") swaps the same modal to the tile form. Avoids
// a second modal type / navigation stack for what's really one flow.
function tileListEditorModal() {
  const m = UI.modal;
  const section = State.homeSections.find((s) => s.id === m.sectionId);
  if (!section) return "";
  if (m.editingTileId != null) return tileFormModal(section, m.editingTileId);
  const config = TILE_TYPE_CONFIG[section.type];
  const tiles = sortedTiles(section);
  return `
  <div class="overlay" data-action="close-modal-backdrop">
    <div class="dialog dialog-static dialog-promo" role="dialog" aria-modal="true" data-action="noop">
      <div class="dialog-head"><span>${esc((HOME_SECTION_TYPE_META[section.type] || {}).label || section.type)}</span><button class="dialog-close" data-action="close-modal">${ic("close")}</button></div>
      <div class="dialog-body">
        <button class="btn btn-primary" data-action="add-tile" data-section="${section.id}">${ic("plus")} Add tile</button>
        <div class="admin-table" style="margin-top:12px">
          ${tiles.length === 0 ? `<div class="empty-state"><div class="empty-title">No tiles yet</div><div class="empty-hint">This section won't show on the customer home screen until it has at least one tile.</div></div>` : tiles.map((t) => tileRowHTML(section, t, config)).join("")}
        </div>
      </div>
    </div>
  </div>`;
}
function tileRowHTML(section, t, config) {
  const media = config.media === "icon"
    ? `<span class="admin-row-img" style="display:flex;align-items:center;justify-content:center;background:var(--tint);color:var(--primary)">${ic(t.icon || "check")}</span>`
    : `<img src="${t.image || ""}" class="admin-row-img" alt="" />`;
  return `
  <div class="admin-row tile-row" data-tile-id="${esc(t.id)}">
    <span class="drag-handle" draggable="true" aria-label="Drag to reorder">☰</span>
    ${media}
    <div class="admin-row-info">
      <div class="admin-row-name">${esc(t.title)}</div>
      ${t.subtitle ? `<div class="qk-muted small">${esc(t.subtitle)}</div>` : ""}
    </div>
    <button class="icon-btn" data-action="edit-tile" data-section="${section.id}" data-tile="${esc(t.id)}" aria-label="Edit">${ic("edit")}</button>
    <button class="icon-btn icon-btn-danger" data-action="delete-tile" data-section="${section.id}" data-tile="${esc(t.id)}" aria-label="Delete">${ic("trash")}</button>
  </div>`;
}
function tileFormModal(section, editingTileId) {
  const isNew = editingTileId === "new";
  const config = TILE_TYPE_CONFIG[section.type];
  const t = isNew ? { title: "", subtitle: "", image: "", icon: "check", catId: null, tag: "" } : sortedTiles(section).find((x) => x.id === editingTileId) || {};
  return `
  <div class="overlay" data-action="close-modal-backdrop">
    <div class="dialog dialog-static" role="dialog" aria-modal="true" data-action="noop">
      <div class="dialog-head"><span>${isNew ? "Add tile" : "Edit tile"}</span><button class="dialog-close" data-action="close-modal">${ic("close")}</button></div>
      <form class="dialog-body" data-action="save-tile" data-section="${section.id}" data-tile="${isNew ? "new" : esc(editingTileId)}">
        <button type="button" class="link-btn" data-action="back-to-tile-list" data-section="${section.id}" style="margin-bottom:10px">${ic("chevronLeft")} Back to ${esc((HOME_SECTION_TYPE_META[section.type] || {}).label || section.type)}</button>
        ${config.media === "image" ? `
        <div class="form-media-row">
          <img src="${t.image || ""}" class="form-media-preview" alt="" />
          <label class="field"><span class="field-label">Image URL</span><input class="input" name="image" value="${esc(t.image || "")}" /></label>
        </div>` : `
        <label class="field"><span class="field-label">Icon</span>
          <select class="input" name="icon">${TRUST_ICON_OPTIONS.map((o) => `<option value="${o.key}" ${(t.icon || "check") === o.key ? "selected" : ""}>${esc(o.label)}</option>`).join("")}</select>
        </label>`}
        <label class="field"><span class="field-label">Title *</span><input class="input" name="title" value="${esc(t.title || "")}" /></label>
        <label class="field"><span class="field-label">Subtitle</span><input class="input" name="subtitle" value="${esc(t.subtitle || "")}" /></label>
        ${config.link === "category" ? `
        <label class="field"><span class="field-label">Links to category</span>
          <select class="input" name="catId">${State.categories.map((c) => `<option value="${c.id}" ${t.catId === c.id ? "selected" : ""}>${esc(c.name)}</option>`).join("")}</select>
        </label>` : ""}
        ${config.link === "tag" ? `
        <label class="field"><span class="field-label">Links to</span>
          <select class="input" name="tag">${TILE_TAG_OPTIONS.map((o) => `<option value="${o.key}" ${t.tag === o.key ? "selected" : ""}>${esc(o.label)}</option>`).join("")}</select>
        </label>` : ""}
        ${UI.modal.error ? `<div class="field-error">${esc(UI.modal.error)}</div>` : ""}
        <div class="form-actions">
          <button type="button" class="btn btn-outline btn-block" data-action="back-to-tile-list" data-section="${section.id}">Cancel</button>
          <button type="submit" class="btn btn-primary btn-block">${isNew ? "Add tile" : "Save changes"}</button>
        </div>
      </form>
    </div>
  </div>`;
}

