// Role provides the DEFAULTS; each permission row here is pre-filled from
// the selected role's template but is independently editable — whatever the
// Super Admin leaves different from the role default is saved as this one
// user's override (see Submits["save-user"]). Store assignment is a totally
// separate control (storeIds) — it decides WHICH store's data this user can
// touch, never WHAT they're allowed to do there.
function userFormModal() {
  const f = UI.modal.form;
  const err = UI.modal.errors || {};
  const me = currentUser();
  const roleOptions = State.roles.filter((r) => r.id !== ROLE_SUPER_ADMIN || isSuperAdmin(me));
  const selectedRole = findRole(f.roleId) || findRole(ROLE_STORE_MANAGER);
  const overrides = f.permissionOverrides || {};
  const isTargetSuperAdmin = f.roleId === ROLE_SUPER_ADMIN;
  return `
  <div class="overlay" data-action="close-modal-backdrop">
    <div class="dialog dialog-static dialog-user" role="dialog" aria-modal="true" data-action="noop">
      <div class="dialog-head"><span>${f.id ? "Edit user" : "Add user"}</span><button class="dialog-close" data-action="close-modal">${ic("close")}</button></div>
      <form class="dialog-body" data-action="save-user">
        <label class="field"><span class="field-label">Full name *</span><input class="input ${err.name ? "invalid" : ""}" name="name" value="${esc(f.name)}" /></label>
        <div class="field-grid-2">
          <label class="field"><span class="field-label">Email</span><input class="input" name="email" value="${esc(f.email || "")}" /></label>
          <label class="field"><span class="field-label">Mobile number</span><input class="input" name="mobile" value="${esc(f.mobile || "")}" /></label>
        </div>
        <label class="field"><span class="field-label">Password</span><input class="input" type="password" name="password" placeholder="${f.id ? "Leave blank to keep unchanged" : "Set a demo password"}" autocomplete="new-password" /></label>
        <label class="field"><span class="field-label">Role / Profile</span>
          <select class="input" name="roleId">${roleOptions.map((r) => `<option value="${r.id}" ${f.roleId === r.id ? "selected" : ""}>${esc(r.name)}</option>`).join("")}</select>
        </label>
        <span class="field-label">Assigned store(s)</span>
        <div class="store-check-list">
          ${State.branches.map((b) => `<label class="check-row"><input type="checkbox" name="storeIds" value="${b.id}" ${(f.storeIds || []).includes(b.id) ? "checked" : ""} /> ${esc(b.name)}</label>`).join("")}
        </div>
        <div class="qk-muted small" style="margin:2px 0 14px">${isTargetSuperAdmin ? "Ignored for Super Admin — always has access to every store." : "Pick one store for a normal Store Manager, or several for a user covering more than one."}</div>
        <label class="stock-toggle-lg"><input type="checkbox" name="active" ${f.active !== false ? "checked" : ""} /><span>Active — can sign in</span></label>

        <div class="summary-card-title" style="margin-top:16px">Permissions</div>
        <div class="qk-muted small" style="margin-bottom:8px">Pre-filled from the ${esc(selectedRole ? selectedRole.name : "")} role — change any row to override it for just this user.</div>
        <div class="perm-grid">
          ${PERMISSION_SCREENS.map((s) => {
            const eff = overrides[s.key] != null ? overrides[s.key] : (isTargetSuperAdmin ? "edit" : roleDefaultPermission(f.roleId, s.key));
            return `<div class="perm-row"><span>${s.label}</span>${permissionSelect(s.key, eff, s.editable, isTargetSuperAdmin, "user")}</div>`;
          }).join("")}
        </div>
        ${isTargetSuperAdmin ? `<div class="qk-muted small" style="margin-top:8px">Super Admin always has full access — permissions above are informational only.</div>` : ""}

        <div class="form-actions" style="margin-top:16px">
          <button type="button" class="btn btn-outline btn-block" data-action="close-modal">Cancel</button>
          <button type="submit" class="btn btn-primary btn-block">${f.id ? "Save changes" : "Add user"}</button>
        </div>
      </form>
    </div>
  </div>`;
}

