/* ---------------- Rider shell ---------------- */
function viewRiderShell() {
  const session = State.session;
  const busy = riderIsBusy(session.partnerId);
  const ready = riderIsReady(session.partnerId);
  const startedAt = State.shiftStart[session.partnerId] || null;
  const onShift = !!startedAt;
  const branch = findBranch(findPartner(session.partnerId) && findPartner(session.partnerId).branchId);
  const statusLabel = busy ? "On a trip" : ready ? "Online — the store assigns your orders" : "Offline";
  return `
  <div class="site">
    <header class="topbar rider-topbar">
      <div class="topbar-row container">
        <button class="brand-btn" data-action="noop"><span class="brand-tile"><img src="${State.siteCustomization.branding.logoUrl}" alt="" /></span><span class="brand-word">MyShopza</span></button>
        <div class="rider-title"><div class="qk-muted small" style="color:rgba(255,255,255,.75)">Delivery partner${branch ? ` · ${esc(branch.name)}` : ""}</div><div class="rider-name">${esc(session.name)}</div></div>
        <nav class="topbar-actions">
          <span class="online-toggle ${ready ? "on" : ""}"><span class="status-dot ${busy ? "busy" : ready ? "on" : ""}"></span>${statusLabel}</span>
          ${!busy && !ready ? `<button class="topbar-link" data-action="go-ready" style="background:var(--success)">${ic("check")}<span>Go online</span></button>` : ""}
          ${!busy && ready ? `<button class="topbar-link" data-action="leave-ready-queue">Pause</button>` : ""}
          ${!busy && onShift ? `<button class="topbar-link" data-action="end-shift-request">${ic("clock")}<span>End shift</span></button>` : ""}
          <button class="topbar-link" data-action="logout">${ic("logout")}<span>Logout</span></button>
        </nav>
      </div>
    </header>
    <main class="site-main">
      <div class="container section">
        <div class="pill-row">
          <button class="pill ${UI.riderTab === "deliveries" ? "active" : ""}" data-action="rider-tab" data-tab="deliveries">${ic("truck")} Deliveries</button>
          <button class="pill ${UI.riderTab === "history" ? "active" : ""}" data-action="rider-tab" data-tab="history">${ic("package")} History</button>
          <button class="pill ${UI.riderTab === "earnings" ? "active" : ""}" data-action="rider-tab" data-tab="earnings">${ic("wallet")} Earnings</button>
        </div>
        ${onShift ? `<div class="qk-muted small" style="display:flex;align-items:center;gap:6px;margin:-4px 0 10px">${ic("clock")} On shift since ${fmtTime(startedAt)}</div>` : ""}
        ${riderTabContent(session, ready)}
      </div>
    </main>
  </div>
  <div id="toastHolder" class="toast-holder"></div>
  ${modalLayer()}`;
}

function riderTabContent(session, ready) {
  // 2026-09 Round 4: every order assigned to this rider (from Confirmed on), grouped into trips by slot.
  const mine = riderOpenOrders(session.partnerId).sort((a, b) => sectorOf(a).localeCompare(sectorOf(b)));
  const history = State.orders.filter((o) => o.deliveryPartnerId === session.partnerId && TERMINAL_STATUSES.includes(o.status)).sort((a, b) => b.createdAt - a.createdAt);
  if (UI.riderTab === "history") return riderHistory(history);
  if (UI.riderTab === "earnings") return riderEarnings(history);
  if (!mine.length) {
    return `<div class="empty-state empty-wide"><div class="empty-title">No deliveries right now</div><div class="empty-hint">${ready ? "You're online — the store will assign your next trip." : "Tap “Go online” above so the store can assign you orders."}</div></div>`;
  }
  const partner = findPartner(session.partnerId);
  const trips = new Map();
  mine.forEach((o) => { const k = tripKey(o); if (!trips.has(k)) trips.set(k, []); trips.get(k).push(o); });
  return `
  <div class="qk-muted small" style="margin-bottom:8px">${mine.length} order${mine.length === 1 ? "" : "s"} assigned · your ${esc(partner ? partner.vehicle : "vehicle")} carries ${riderCapacity(partner)} per trip. Stops are sorted by postcode.</div>
  ${[...trips.entries()].map(([k, list]) => `
    <div class="rider-trip">
      <div class="rider-trip-head"><b>Trip · ${esc(tripLabel(k))}</b><span class="qk-muted small">${list.length} stop${list.length === 1 ? "" : "s"} · ${list.filter((o) => o.status === "picked_up").length} out</span></div>
      <div class="admin-orders-list">${list.map((o) => riderOrderCard(o)).join("")}</div>
    </div>`).join("")}`;
}

function riderOrderCard(order) {
  const open = UI.riderOpenId === order.id;
  const allMarked = order.items.every((it) => it.unavailable || it.delivered);
  return `
  <div class="admin-order-card">
    <button class="admin-order-head" data-action="toggle-rider-order" data-id="${order.id}">
      <div><div class="order-row-id">#${order.id}</div><div class="qk-muted small">${esc(order.customerName)} · ${order.items.length} item${order.items.length > 1 ? "s" : ""} · ${money(order.total)}</div></div>
      <span class="badge badge-${PREP_STATUSES.includes(order.status) ? "gray" : STATUS_META[order.status].tone}-soft">${PREP_STATUSES.includes(order.status) ? "Being packed" : STATUS_META[order.status].label}</span>
    </button>
    ${open ? `
      <div class="admin-order-body">
        <div class="qk-muted small">${ic("pin")} ${esc(order.address)}</div>
        ${PREP_STATUSES.includes(order.status) ? `<div class="notice notice-warn" style="margin:6px 0">${ic("clock")}<span>Still being packed at the store — collect it when it's ready.</span></div>` : ""}
        ${order.deliveryInstructions ? `<div class="notice notice-warn" style="margin:6px 0">${ic("bell")}<span>${esc(order.deliveryInstructions)}</span></div>` : ""}
        ${order.contactName || order.contactMobile ? `
          <div class="rider-contact">
            <span>${esc(order.contactName || order.customerName)}${order.contactMobile ? ` · ${fmtMobile(order.contactMobile)}` : ""}</span>
            ${order.contactMobile ? `<a class="btn btn-primary btn-sm" href="tel:+65${order.contactMobile}">${ic("phone")} Call</a>` : ""}
          </div>` : ""}
        ${order.items.map((it, idx) => it.unavailable ? `
          <div class="row"><span class="qk-muted" style="text-decoration:line-through">${it.qty} × ${esc(it.name)}</span><span class="badge badge-red-soft">Out of stock</span></div>
        ` : `
          <div class="rider-item-row">
            <div><b>${it.qty} ×</b> ${esc(it.name)}</div>
            <div class="rider-mark-grid">
              ${["delivered", "missing", "damaged"].map((s) => `<button class="mark-btn mark-${s} ${it.delivered === s ? "active" : ""}" data-action="mark-item" data-order="${order.id}" data-idx="${idx}" data-mark="${s}">${s}</button>`).join("")}
            </div>
          </div>`).join("")}
        <div class="form-actions">
          ${order.status === "ready_for_rider" ? `<button class="btn btn-outline btn-block" data-action="start-delivery" data-id="${order.id}">Mark picked up from store</button>` : ""}
          <button class="btn btn-primary-soft btn-block" data-action="complete-delivery" data-id="${order.id}" ${allMarked ? "" : "disabled"}>Complete delivery</button>
        </div>
        ${!allMarked ? `<div class="qk-muted small" style="text-align:center">Mark every item above to finish this delivery.</div>` : ""}
      </div>` : ""}
  </div>`;
}

function riderHistory(orders) {
  if (!orders.length) return `<div class="empty-state"><div class="empty-title">No completed deliveries yet.</div></div>`;
  return `<div class="admin-orders-list">${orders.map((order) => `
    <div class="admin-order-card">
      <div class="admin-order-head" style="cursor:default">
        <div><div class="order-row-id">#${order.id}</div><div class="qk-muted small">${fmtDate(order.createdAt)} · ${order.items.length} item${order.items.length > 1 ? "s" : ""}</div></div>
        <span class="badge badge-${STATUS_META[order.status].tone}">${STATUS_META[order.status].label}</span>
      </div>
      <div class="admin-order-body">
        <div class="row"><span class="qk-muted">${esc(order.address)}</span><span>${order.riderEarning ? `+${money(order.riderEarning)}` : "—"}</span></div>
        ${order.rating ? `<div class="qk-muted small">Customer rated: ${starsHTML(order.rating, true)}</div>` : ""}
      </div>
    </div>`).join("")}</div>`;
}

function riderEarnings(orders) {
  const now = new Date();
  const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const startOfWeek = startOfDay - now.getDay() * 86400000;
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
  const delivered = orders.filter((o) => o.status === "delivered");
  const sumSince = (ts) => delivered.filter((o) => o.createdAt >= ts).reduce((s, o) => s + (o.riderEarning || 0), 0);
  const countSince = (ts) => delivered.filter((o) => o.createdAt >= ts).length;
  const totalEarned = delivered.reduce((s, o) => s + (o.riderEarning || 0), 0);
  const rated = delivered.filter((o) => o.rating);
  const avgRating = rated.length ? rated.reduce((s, o) => s + o.rating, 0) / rated.length : null;
  return `
  <div class="stat-grid">
    <div class="stat-card"><div class="stat-label">Today</div><div class="stat-value">${money(sumSince(startOfDay))}</div><div class="stat-sub">${countSince(startOfDay)} deliveries</div></div>
    <div class="stat-card"><div class="stat-label">This week</div><div class="stat-value">${money(sumSince(startOfWeek))}</div><div class="stat-sub">${countSince(startOfWeek)} deliveries</div></div>
    <div class="stat-card"><div class="stat-label">This month</div><div class="stat-value">${money(sumSince(startOfMonth))}</div><div class="stat-sub">${countSince(startOfMonth)} deliveries</div></div>
    <div class="stat-card"><div class="stat-label">All-time</div><div class="stat-value">${money(totalEarned)}</div><div class="stat-sub">${delivered.length} deliveries</div></div>
  </div>
  <div class="summary-card row" style="justify-content:space-between;align-items:center">
    <div><div class="qk-muted small">Average rating</div><div class="stat-value-sm">${avgRating ? avgRating.toFixed(1) : "—"}</div></div>
    ${avgRating != null ? starsHTML(Math.round(avgRating), true) : ""}
  </div>
  <div class="qk-muted small" style="text-align:center;margin-top:10px">${money(RIDER_FLAT_FEE)} earned per completed delivery.</div>`;
}

