/* ---------------- Cart mutations ---------------- */
function incCart(id) { State.cart[id] = (State.cart[id] || 0) + 1; persist("cart"); render(); }
function decCart(id) {
  const q = (State.cart[id] || 0) - 1;
  if (q <= 0) delete State.cart[id]; else State.cart[id] = q;
  persist("cart"); render();
}

/* ---------------- Address helpers ---------------- */
const EMPTY_ADDRESS = { label: "Home", name: "", mobile: "", line1: "", line2: "", city: "Singapore", postal: "" };
function openAddressModal(origin) {
  UI.addressOrigin = origin;
  UI.addressForm = null;
  UI.modal = { type: "address" };
  render();
}
function validateAddress(f) {
  const e = {};
  if (!f.name.trim()) e.name = "Enter the name we should ask for at the door";
  if (!normaliseSgMobile(f.mobile)) e.mobile = "Enter a valid 8-digit Singapore mobile number";
  if (!f.line1.trim()) e.line1 = "Enter the block and street";
  if (!/^\d{6}$/.test(String(f.postal).trim())) e.postal = "Postal code must be 6 digits";
  return e;
}

/* ---------------- Order actions (customer) ---------------- */
function handlePay(method) {
  const isPickup = UI.fulfillment === "pickup";
  const addr = getSelectedAddress();
  if (!isPickup && !addr) return;
  const t = cartTotals();
  const store = isPickup ? findPickupBranch(UI.pickupStoreId) : null;
  if (isPickup && !store) return;
  // 2026-09: the same checks the checkout screen shows — a covering store
  // that has everything (unless negative stock is allowed) and a bookable slot.
  const assign = checkoutAssignment();
  const speed = isPickup ? null : effectiveDeliverySpeed();
  if (!assign.branch || isCustomerBlocked(State.session.name)) return;
  if (speed === "scheduled" && !selectedSlotValid(assign.branch)) return;
  const orderItems = t.cartItems.map((i) => ({ id: i.id, name: i.name, unit: i.unit, price: i.price, eta: i.eta, qty: i.qty, bogo: isBogo(i.id), delivered: null }));
  const branch = assign.branch;
  const slotKeyPicked = speed === "scheduled" ? UI.scheduledSlot : null;
  const order = {
    id: genId("QK"), invoiceNo: genId("INV-"), customerName: State.session.name,
    contactName: addr ? addr.name || State.session.name : State.session.name,
    contactMobile: addr ? addr.mobile || "" : "",
    addressType: isPickup ? "Pickup" : addr ? addr.label : null,
    address: isPickup ? `${store.name} - ${store.pickupAddress}` : addr ? [addr.label + " -", addr.line1, addr.line2, `${addr.city} ${addr.postal}`].filter(Boolean).join(", ").replace(" -,", " -") : "No address on file",
    fulfillment: UI.fulfillment, pickupStoreId: isPickup ? store.id : null,
    branchId: branch ? branch.id : null,
    items: orderItems, total: t.grandTotal, itemTotal: t.totalPrice, deliveryFee: t.deliveryFee, expressCharge: t.expressCharge,
    discount: t.savings, bogoSavings: t.bogoSavings, comboDiscount: t.comboDiscount, activeCombos: activeCombos().map((c) => c.title),
    couponCode: t.couponValid ? t.appliedCoupon.code : null, couponDiscount: t.couponDiscount, couponFreeShip: t.couponFreeShip,
    walletApplied: t.walletApplied, paymentMethod: method, status: "new",
    // Frozen at purchase time so a later admin change to the tax name/rate/
    // inclusive-vs-exclusive setting never rewrites how a past order's
    // invoice reads — its own historical rate/mode and the tax amount
    // actually charged both travel with the order.
    taxSnapshot: { ...State.tax }, gst: t.gst,
    deliveryInstructions: isPickup ? null : UI.deliveryInstructions.trim() || null,
    deliverySpeed: speed, scheduledSlot: slotKeyPicked ? slotLabelFromKey(slotKeyPicked) : null, slotKey: slotKeyPicked,
    deliveryPartnerId: null, rating: null, riderEarning: 0, createdAt: Date.now(),
    statusHistory: [{ status: "new", at: Date.now() }],
  };
  State.orders.unshift(order); persist("orders");
  // 2026-09: book the slot and take the stock from the assigned store.
  if (slotKeyPicked) { State.slotBookings = { ...State.slotBookings, [slotKeyPicked]: (State.slotBookings[slotKeyPicked] || 0) + 1 }; persist("slotBookings"); }
  // Round 5: take the stock from the nearest store. Negative stock OFF → it stops at 0;
  // ON → it may go below 0. Either way the missing quantity is flagged on the line as
  // `short`, so the store can transfer it from a nearby store or mark it unavailable.
  order.items.forEach((it) => {
    const before = storeQty(branch.id, it.id);
    if (before == null) return;
    const have = Math.max(before, 0);
    const take = allowNegativeStock() ? it.qty : Math.min(it.qty, have);
    if (take > 0) recordStockMove({ branchId: branch.id, itemId: it.id, type: "sale", qty: -take, ref: `Order #${order.id}` });
    const short = Math.max(0, it.qty - have);
    if (short) it.short = short;
  });
  persist("orders");
  if (t.walletApplied > 0) { State.wallet = Math.max(State.wallet - t.walletApplied, 0); persist("wallet"); }
  UI.lastOrderId = order.id;
  State.cart = {}; persist("cart");
  UI.useWallet = false;
  UI.deliveryInstructions = "";
  UI.deliverySpeed = "express";
  UI.scheduledSlot = null;
  UI.fulfillment = "delivery";
  UI.appliedCoupon = null;
  UI.couponCode = "";
  UI.couponError = null;
  UI.paid = true;
  render();
}

function resolveUnavailable(order, itemIdx, resolution, method) {
  const orderItem = order.items[itemIdx];
  const catalogItem = findItem(orderItem.id);
  const requestedAltId = orderItem.changeRequest && orderItem.changeRequest.altId;
  const altItem = requestedAltId ? findItem(requestedAltId) : (catalogItem && catalogItem.altId ? findItem(catalogItem.altId) : null);
  const refundAmount = orderItem.price * orderItem.qty;
  const swapAmount = altItem ? altItem.price * orderItem.qty : 0;
  const diff = swapAmount - refundAmount;
  if (resolution === "swap" && diff > 0.01 && !method) {
    UI.payDiffFor = { orderId: order.id, itemIdx };
    UI.modal = { type: "payDiff" };
    render();
    return;
  }
  const idx = State.orders.findIndex((o) => o.id === order.id);
  const o = State.orders[idx];
  const newItems = o.items.map((it, i) => {
    if (i !== itemIdx) return it;
    if (resolution === "swap" && altItem) return { ...it, id: altItem.id, name: altItem.name, unit: altItem.unit, price: altItem.price, unavailable: false, resolution: "swap" };
    return { ...it, unavailable: false, resolution };
  });
  const newTotal = resolution === "swap" ? o.total - refundAmount + swapAmount : o.total - refundAmount;
  State.orders[idx] = { ...o, items: newItems, total: Math.max(newTotal, 0) };
  persist("orders");
  if (resolution === "wallet") {
    const bonusAmount = refundAmount * 1.1;
    State.wallet += bonusAmount; persist("wallet");
    pushNotice(`${money(bonusAmount)} credited to your wallet (includes a 10% bonus) for the unavailable ${orderItem.name}.`);
  } else if (resolution === "original") {
    pushNotice(`${money(refundAmount)} will be refunded to your ${order.paymentMethod} within 3-5 business days.`);
  } else if (resolution === "swap" && altItem) {
    if (diff > 0.01) pushNotice(`${orderItem.name} was replaced with ${altItem.name} on order #${order.id} — ${money(diff)} difference paid via ${method}.`);
    else if (diff < -0.01) { State.wallet += -diff; persist("wallet"); pushNotice(`${orderItem.name} was replaced with ${altItem.name} on order #${order.id} — the replacement was cheaper, so ${money(-diff)} was credited to your wallet.`); }
    else pushNotice(`${orderItem.name} was replaced with ${altItem.name} on order #${order.id}.`);
  }
  UI.payDiffFor = null;
  UI.modal = null;
  render();
}

