    const used = State.items.filter((i) => i.cat === c.name).length;
    if (used > 0) { showToast(`${c.name} still has ${used} item(s) — move them first`, "danger"); return; }
    if (!window.confirm(`Delete the "${c.name}" category?`)) return;
